:root {
  --ink: #eaffff;
  --muted: #8fb9c4;
  --cyan: #6ef3ff;
  --amber: #ffc247;
  --orange: #ff7a3d;
  --pink: #ff5d8f;
  --deep: #020b12;
  --glass: rgba(4, 22, 32, 0.52);
  --stroke: rgba(126, 241, 255, 0.18);
  --font-display: "Arial Black", "Arial Bold", "Trebuchet MS", system-ui, sans-serif;
  --font-body: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  --pad-top: env(safe-area-inset-top, 0px);
  --pad-right: env(safe-area-inset-right, 0px);
  --pad-bottom: env(safe-area-inset-bottom, 0px);
  --pad-left: env(safe-area-inset-left, 0px);
}

* { box-sizing: border-box; }

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--deep);
  color: var(--ink);
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#game {
  position: fixed;
  inset: 0;
  display: block;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  touch-action: none;
}
body.playing #game { cursor: none; }

#safe-probe {
  position: fixed;
  inset: 0;
  visibility: hidden;
  pointer-events: none;
  padding: env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px) env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px);
}

.hidden { display: none !important; }

/* ---------- top action buttons ---------- */
.top-actions {
  position: fixed;
  top: calc(14px + var(--pad-top));
  right: calc(14px + var(--pad-right));
  z-index: 30;
  display: flex;
  gap: 9px;
}
.icon-btn {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  border: 1px solid var(--stroke);
  background: rgba(4, 20, 30, 0.55);
  color: var(--ink);
  display: grid;
  place-items: center;
  cursor: pointer;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: transform 0.15s ease, background 0.2s ease, border-color 0.2s ease;
}
.icon-btn:hover { background: rgba(20, 64, 78, 0.7); border-color: rgba(110, 243, 255, 0.5); transform: translateY(-1px); }
.icon-btn:active { transform: scale(0.94); }
.icon-btn svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn svg path:first-child { fill: currentColor; stroke: none; }
.icon-btn .icon-off { display: none; }
.icon-btn.muted .icon-on { display: none; }
.icon-btn.muted .icon-off { display: block; }

/* ---------- screens ---------- */
.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  overflow: auto;
  padding: calc(20px + var(--pad-top)) calc(20px + var(--pad-right)) calc(20px + var(--pad-bottom)) calc(20px + var(--pad-left));
  background:
    radial-gradient(120% 90% at 50% 8%, rgba(8, 54, 72, 0.36), transparent 60%),
    radial-gradient(80% 60% at 50% 105%, rgba(0, 7, 12, 0.8), transparent 70%),
    linear-gradient(180deg, rgba(2, 12, 20, 0.46), rgba(1, 8, 14, 0.78));
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  animation: screenIn 0.4s ease both;
}
@keyframes screenIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
.screen.menu-screen {
  place-items: center;
  background:
    radial-gradient(90% 70% at 50% 45%, rgba(2, 12, 20, 0.18), rgba(1, 7, 12, 0.74) 100%),
    linear-gradient(180deg, rgba(2, 12, 20, 0.42), rgba(1, 7, 12, 0.76));
}
.menu-inner {
  width: min(760px, 100%);
  margin: auto;
  text-align: center;
  padding: 10px 0 4px;
}
.eyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 0 0 14px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.36em;
  text-transform: uppercase;
  color: var(--cyan);
  text-shadow: 0 0 16px rgba(110, 243, 255, 0.35);
}
.eyebrow span { width: 34px; height: 1px; background: linear-gradient(90deg, transparent, var(--cyan)); }
.eyebrow span:last-child { transform: scaleX(-1); }
.eyebrow.danger { color: var(--pink); text-shadow: 0 0 16px rgba(255, 93, 143, 0.35); }
.eyebrow.danger span { background: linear-gradient(90deg, transparent, var(--pink)); }

.logo {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 900;
  line-height: 0.82;
  letter-spacing: -0.055em;
  text-transform: uppercase;
  transform: skewX(-4deg);
  filter: drop-shadow(0 18px 40px rgba(0, 0, 0, 0.45));
}
.logo-line { display: block; }
.logo-reef {
  font-size: clamp(3.6rem, 15vw, 8.2rem);
  color: #f3fffe;
  text-shadow: 0 0 40px rgba(110, 243, 255, 0.28), 0 4px 0 rgba(6, 40, 50, 0.65);
  letter-spacing: 0.02em;
}
.logo-rampage {
  font-size: clamp(2.7rem, 11.5vw, 6.3rem);
  color: transparent;
  -webkit-text-stroke: clamp(1.5px, 0.28vw, 2.6px) var(--amber);
  text-stroke: 2px var(--amber);
  text-shadow: 0 0 34px rgba(255, 194, 71, 0.28);
  margin-top: 0.06em;
}
.tagline {
  margin: 20px 0 0;
  font-size: clamp(0.95rem, 2.4vw, 1.15rem);
  letter-spacing: 0.04em;
  color: #d7f5f6;
  font-weight: 600;
}
.tagline em { color: var(--amber); font-style: normal; }

.primary-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  margin-top: 26px;
  padding: 18px 38px;
  min-width: 236px;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(180deg, #ffd979, #ffb42e 55%, #ff8f2e);
  color: #1c1103;
  font-family: var(--font-display);
  font-size: 1.08rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow:
    0 0 0 1px rgba(255, 230, 170, 0.5) inset,
    0 12px 32px rgba(255, 148, 41, 0.28),
    0 0 60px rgba(255, 180, 46, 0.12);
  transition: transform 0.16s ease, box-shadow 0.2s ease, filter 0.2s ease;
  overflow: hidden;
}
.primary-btn::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 20%, rgba(255, 255, 255, 0.5) 48%, transparent 70%);
  transform: translateX(-130%);
  animation: btnShine 3.6s ease-in-out infinite;
}
@keyframes btnShine {
  0%, 55% { transform: translateX(-130%); }
  80%, 100% { transform: translateX(130%); }
}
.primary-btn:hover { transform: translateY(-2px) scale(1.015); box-shadow: 0 16px 42px rgba(255, 148, 41, 0.38), 0 0 70px rgba(255, 180, 46, 0.2); }
.primary-btn:active { transform: translateY(1px) scale(0.98); }
.primary-btn:focus-visible, .ghost-btn:focus-visible, .text-btn:focus-visible, .icon-btn:focus-visible {
  outline: 3px solid var(--cyan);
  outline-offset: 3px;
}
.primary-btn span { position: relative; z-index: 1; }
.primary-btn kbd { position: relative; z-index: 1; }
.primary-btn.small { margin-top: 0; padding: 15px 30px; min-width: 200px; font-size: 0.98rem; }

kbd {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background: rgba(255, 255, 255, 0.08);
  font-family: var(--font-body);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: inherit;
}
.primary-btn kbd {
  border-color: rgba(30, 15, 0, 0.25);
  background: rgba(30, 15, 0, 0.12);
}

.best-line {
  margin: 16px 0 0;
  font-size: 0.72rem;
  letter-spacing: 0.28em;
  color: var(--muted);
  font-weight: 700;
}
.best-line strong { color: var(--cyan); font-size: 0.95rem; letter-spacing: 0.12em; margin-left: 4px; }

.controls {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 30px;
}
.control-card {
  flex: 1 1 150px;
  max-width: 190px;
  padding: 13px 12px 11px;
  border-radius: 14px;
  border: 1px solid rgba(126, 241, 255, 0.14);
  background: linear-gradient(180deg, rgba(11, 43, 56, 0.5), rgba(4, 20, 30, 0.45));
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.control-icon { display: block; font-size: 1rem; color: var(--cyan); opacity: 0.8; line-height: 1; }
.control-card h3 {
  margin: 7px 0 6px;
  font-size: 0.64rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: #c7eef2;
}
.control-card p { margin: 0; font-size: 0.68rem; letter-spacing: 0.08em; color: var(--muted); line-height: 1.9; }
.control-card kbd { font-size: 0.56rem; padding: 2px 5px; }
.touch-only { display: none; }
.hint {
  margin: 22px 0 0;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  color: rgba(143, 185, 196, 0.72);
}

/* ---------- pause / game over ---------- */
.panel {
  width: min(480px, 100%);
  padding: clamp(26px, 5vw, 40px) clamp(22px, 5vw, 44px);
  border-radius: 26px;
  border: 1px solid rgba(126, 241, 255, 0.18);
  background:
    linear-gradient(180deg, rgba(9, 39, 52, 0.78), rgba(3, 16, 25, 0.9));
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(255, 255, 255, 0.03) inset;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  text-align: center;
  animation: panelIn 0.35s cubic-bezier(0.2, 1.2, 0.4, 1) both;
}
@keyframes panelIn {
  from { opacity: 0; transform: translateY(18px) scale(0.97); }
  to { opacity: 1; transform: none; }
}
.panel-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2.8rem, 10vw, 4.4rem);
  line-height: 0.9;
  letter-spacing: -0.04em;
  text-transform: uppercase;
  color: #f3fffe;
  text-shadow: 0 0 40px rgba(110, 243, 255, 0.2);
}
.panel-title.chomped {
  color: transparent;
  -webkit-text-stroke: 2px var(--pink);
  text-stroke: 2px var(--pink);
  text-shadow: 0 0 40px rgba(255, 93, 143, 0.3);
  transform: skewX(-4deg);
}
.panel-sub { margin: 12px 0 0; color: var(--muted); font-size: 0.88rem; letter-spacing: 0.05em; }
.panel-actions { display: flex; flex-direction: column; align-items: center; gap: 12px; margin-top: 26px; }
.ghost-btn, .text-btn {
  border: 0;
  background: transparent;
  color: #cfeff2;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
  padding: 10px 14px;
  border-radius: 10px;
  transition: color 0.2s ease, background 0.2s ease;
}
.ghost-btn { border: 1px solid rgba(126, 241, 255, 0.22); background: rgba(126, 241, 255, 0.04); }
.ghost-btn:hover, .text-btn:hover { color: #fff; background: rgba(126, 241, 255, 0.1); }
.text-btn { color: var(--muted); font-size: 0.68rem; }

.over-panel .panel-title { margin-bottom: 4px; }
.final-score-label {
  margin: 24px 0 0;
  font-size: 0.66rem;
  letter-spacing: 0.32em;
  color: var(--muted);
  font-weight: 700;
}
.final-score {
  margin: 2px 0 0;
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 9vw, 3.9rem);
  line-height: 1;
  color: var(--amber);
  text-shadow: 0 0 34px rgba(255, 194, 71, 0.3);
  letter-spacing: 0.01em;
}
.new-best {
  display: inline-block;
  margin: 14px 0 0;
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(255, 194, 71, 0.13);
  border: 1px solid rgba(255, 194, 71, 0.42);
  color: var(--amber);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.22em;
  animation: bestPulse 1.4s ease-in-out infinite;
}
@keyframes bestPulse {
  0%, 100% { box-shadow: 0 0 0 rgba(255, 194, 71, 0); }
  50% { box-shadow: 0 0 24px rgba(255, 194, 71, 0.28); }
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 22px 0 0;
  padding: 14px 8px;
  border-radius: 14px;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(126, 241, 255, 0.09);
}
.stats-grid div { display: flex; flex-direction: column; gap: 4px; }
.stats-grid span { font-size: 0.56rem; letter-spacing: 0.2em; color: var(--muted); font-weight: 700; }
.stats-grid strong { font-family: var(--font-display); font-size: 1.25rem; color: #eaffff; }

.rotate-hint {
  position: fixed;
  z-index: 40;
  left: 50%;
  bottom: calc(14px + var(--pad-bottom));
  transform: translateX(-50%);
  display: none;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 999px;
  border: 1px solid var(--stroke);
  background: rgba(4, 20, 30, 0.7);
  backdrop-filter: blur(8px);
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  color: var(--muted);
  pointer-events: none;
}
.rotate-hint span { color: var(--cyan); font-size: 0.9rem; }

/* ---------- responsive ---------- */
@media (pointer: coarse) {
  .desktop-only { display: none !important; }
  .touch-only { display: block; }
  .controls { gap: 8px; }
  .control-card { flex-basis: 110px; }
  .hint { display: none; }
  .primary-btn { margin-top: 22px; }
}
@media (max-width: 680px) {
  .menu-inner { padding-top: 4px; }
  .tagline { margin-top: 16px; }
  .controls { margin-top: 24px; }
  .logo-reef { font-size: clamp(3rem, 19vw, 5.2rem); }
  .logo-rampage { font-size: clamp(2.2rem, 14vw, 4rem); }
  .eyebrow { margin-bottom: 10px; letter-spacing: 0.26em; font-size: 10px; }
  .primary-btn { min-width: 210px; padding: 16px 30px; }
  .best-line { margin-top: 12px; }
  .top-actions { top: calc(10px + var(--pad-top)); right: calc(10px + var(--pad-right)); }
  .icon-btn { width: 42px; height: 42px; }
}
@media (max-height: 700px) {
  .menu-inner { transform: scale(0.92); }
  .logo-reef { font-size: clamp(2.8rem, 12vh, 6rem); }
  .logo-rampage { font-size: clamp(2.1rem, 9.5vh, 4.6rem); }
  .tagline { margin-top: 12px; }
  .primary-btn { margin-top: 16px; padding: 14px 30px; }
  .controls { margin-top: 18px; }
  .best-line { margin-top: 10px; }
  .hint { display: none; }
  .panel { padding: 22px 26px; }
  .final-score-label { margin-top: 16px; }
  .stats-grid { margin-top: 14px; }
  .panel-actions { margin-top: 18px; gap: 9px; }
}
@media (max-width: 420px) and (orientation: portrait) {
  .rotate-hint { display: flex; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001s !important; animation-iteration-count: 1 !important; transition-duration: 0.001s !important; }
}

/**
 * Tiny procedural sound engine — no audio files needed.
 * Everything is synthesized with the Web Audio API on demand.
 */
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuffer = null;
    this.muted = false;
    try {
      this.muted = localStorage.getItem('reef-rampage-muted') === '1';
    } catch { /* storage may be unavailable */ }
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(this.ctx.destination);

    // Pre-render one second of white noise for percussive sounds.
    const length = this.ctx.sampleRate;
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buffer;
  }

  get available() {
