import {
  TAU, WORLD, FLOOR, C, ENEMY_DEFS, WAVE_TAGS, MAG_SIZE, RELOAD_TIME,
  rnd, rndi, clamp, lerp, mod, angleLerp, easeOut, makePlayer, PICKUP_DEFS,
} from './core.js';
import { readSafeInsets } from './input.js';
import { Renderer } from './render.js';

const BEST_KEY = 'reef-rampage-best';

function loadBest() {
  try { return Number(localStorage.getItem(BEST_KEY)) || 0; } catch { return 0; }
}
function saveBest(n) {
  try { localStorage.setItem(BEST_KEY, String(Math.round(n))); } catch { /* ignore */ }
}

export class Game {
  constructor(canvas, input, audio, options = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.input = input;
    this.audio = audio;
    this.options = options;
    this.best = loadBest();
    this.state = 'menu';
    this.t = 0;
    this.last = 0;
    this.dpr = 1;
    this.w = window.innerWidth;
    this.h = window.innerHeight;
    this.safe = { top: 0, right: 0, bottom: 0, left: 0 };
    this.shake = 0;
    this.hurtFlash = 0;
    this.runToken = 0;
    this.aimPoint = null;

    this.renderer = new Renderer(this);
    this.initAmbient();
    this.resize();
    this.setupMenu();

    this._loop = this._loop.bind(this);
    requestAnimationFrame(this._loop);
    window.addEventListener('resize', () => this.resize());
    window.addEventListener('orientationchange', () => setTimeout(() => this.resize(), 120));
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'playing') this.pause();
    });
  }

  /* ------------------------------------------------------------------ */
  /*  setup / lifecycle                                                  */
  /* ------------------------------------------------------------------ */

  resize() {
    this.w = Math.max(320, window.innerWidth);
    this.h = Math.max(320, window.innerHeight);
    this.dpr = clamp(window.devicePixelRatio || 1, 1, 2);
    this.canvas.width = Math.round(this.w * this.dpr);
    this.canvas.height = Math.round(this.h * this.dpr);
    this.canvas.style.width = `${this.w}px`;
    this.canvas.style.height = `${this.h}px`;
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.safe = readSafeInsets();
    this.input.setViewport(this.w, this.h, this.safe);
    this.renderer.resize();
    if (this.camera) this.clampCamera(true);
  }

  emit(state, stats = null) {
    this.options.onState?.(state, stats);
  }

  initAmbient() {
    const a = { bubbles: [], motes: [], bgFish: [], bubbleT: rnd(2, 6) };
    for (let i = 0; i < 80; i++) {
      a.bubbles.push({
        x: rnd(0, WORLD.w),
        y: rnd(0, WORLD.h),
        r: rnd(1.4, 5),
        speed: rnd(16, 52),
        phase: rnd(0, TAU),
        drift: rnd(0.4, 1.4),
      });
    }
    for (let i = 0; i < 130; i++) {
      a.motes.push({
        x: rnd(0, WORLD.w),
        y: rnd(0, WORLD.h),
        r: rnd(0.6, 1.8),
        speed: rnd(3, 14),
        phase: rnd(0, TAU),
      });
    }
    for (let i = 0; i < 11; i++) {
      a.bgFish.push({
        nx: rnd(-150, this.w + 150),
        ny: rnd(0.08, 0.78),
        scale: rnd(0.5, 1.5),
        dir: Math.random() < 0.5 ? -1 : 1,
        speed: rnd(7, 22),
        phase: rnd(0, TAU),
        alpha: rnd(0.035, 0.09),
      });
    }
    this.ambient = a;
  }

  setupMenu() {
    this.state = 'menu';
    this.runToken++;
    this.player = makePlayer(WORLD.w / 2, WORLD.h / 2 - 40);
    this.player.angle = -0.2;
    this.player.aimAngle = -0.2;
    this.camera = { x: this.player.x - this.w / 2, y: this.player.y - this.h / 2 };
    this.enemies = [];
    this.bullets = [];
    this.ebullets = [];
    this.pickups = [];
    this.particles = [];
    this.texts = [];
    this.spawnQueue = [];
    this.rings = [];
    this.boss = null;
    this.banner = null;
    this.wave = 0;
    this.waveState = 'idle';
    this.clearTimer = 0;
    this.score = 0;
    this.kills = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.bestCombo = 0;
    this.lastWaveHadBoss = false;
    this.clampCamera(true);
    this.emit('menu');
  }

  start() {
    this.audio.init();
    this.runToken++;
    this.player = makePlayer(WORLD.w / 2, WORLD.h / 2 - 40);
    this.camera = { x: this.player.x - this.w / 2, y: this.player.y - this.h / 2 };
    this.enemies = [];
    this.bullets = [];
    this.ebullets = [];
    this.pickups = [];
    this.particles = [];
    this.texts = [];
    this.rings = [];
    this.spawnQueue = [];
    this.boss = null;
    this.banner = null;
    this.wave = 0;
    this.waveState = 'idle';
    this.clearTimer = 0;
    this.score = 0;
    this.kills = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.bestCombo = 0;
    this.shake = 0;
    this.hurtFlash = 0;
    this.lastWaveHadBoss = false;
    this.state = 'playing';
    this.input.clearTransient();
    this.input.enabled = true;
    this.clampCamera(true);
    this.emit('playing');
    this.startWave(1);
  }

  pause() {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    this.input.clearTransient();
    this.emit('paused');
  }

  resume() {
    if (this.state !== 'paused') return;
    this.state = 'playing';
    this.input.clearTransient();
    this.emit('playing');
  }

  quitToMenu() {
    this.runToken++;
    this.setupMenu();
    this.input.clearTransient();
  }

  /* ------------------------------------------------------------------ */
  /*  main loop                                                          */
  /* ------------------------------------------------------------------ */

  _loop(ts) {
    if (!this.last) this.last = ts;
    let dt = (ts - this.last) / 1000;
    this.last = ts;
    dt = clamp(dt, 0, 0.033);
    this.t += dt;

    if (this.state === 'playing') this.update(dt);
    else if (this.state === 'menu') this.updateMenu(dt);
    else if (this.state === 'dying' || this.state === 'gameover') this.updateIdle(dt);

    this.renderer.render(this, dt);
    requestAnimationFrame(this._loop);
  }

  update(dt) {
    this.updateAmbient(dt);

    this.player.invuln = Math.max(0, this.player.invuln - dt);
    this.player.fireCd -= dt;
    this.player.dashCd = Math.max(0, this.player.dashCd - dt);
    this.player.recoil = Math.max(0, this.player.recoil - dt * 9);
    this.player.muzzle = Math.max(0, this.player.muzzle - dt);
    this.player.hitT = Math.max(0, this.player.hitT - dt);

    this.aimPoint = this.getAimPoint();
    this.updatePlayer(dt);
    this.updateFiring(dt);
    this.updateBullets(dt);
    this.updateEnemies(dt);
    this.updateEnemyBullets(dt);
    this.updatePickups(dt);
    this.updateWave(dt);
    this.updateEffects(dt);
    this.updateCamera(dt);

    if (this.waveState === 'fighting') {
      for (let i = this.spawnQueue.length - 1; i >= 0; i--) {
        if (this.t >= this.spawnQueue[i].at) {
          const item = this.spawnQueue.splice(i, 1)[0];
          this.spawnEnemy(item.type);
        }
      }
    }

    if (this.comboTimer > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0) this.combo = 0;
    }
  }

  updateMenu(dt) {
    this.updateAmbient(dt);
    this.updateEffects(dt);
    const p = this.player;
    if (!p) return;
    const cx = WORLD.w / 2 + Math.cos(this.t * 0.21) * 210;
    const cy = WORLD.h / 2 - 40 + Math.sin(this.t * 0.3) * 90;
    const tx = cx + Math.cos(this.t * 0.21 + 0.1) * 210;
    const ty = cy + Math.sin(this.t * 0.3 + 0.1) * 90;
    p.x = cx;
    p.y = cy;
    p.angle = angleLerp(p.angle, Math.atan2(ty - cy, tx - cx), 0.05);
    p.moving = true;
    this.aimPoint = this.getAimPoint();
    if (this.aimPoint) {
      p.aimAngle = angleLerp(p.aimAngle, Math.atan2(this.aimPoint.y - p.y, this.aimPoint.x - p.x), 0.08);
    }
    this.camera.x = lerp(this.camera.x, clamp(p.x - this.w / 2, 0, Math.max(0, WORLD.w - this.w)), 0.03);
    this.camera.y = lerp(this.camera.y, clamp(p.y - this.h / 2, 0, Math.max(0, WORLD.h - this.h)), 0.03);
    this.clampCamera(true);
  }

  updateIdle(dt) {
    this.updateAmbient(dt);
    this.updateEffects(dt);
  }

  /* ------------------------------------------------------------------ */
  /*  player                                                             */
  /* ------------------------------------------------------------------ */

  getAimPoint() {
    const p = this.player;
    if (!p) return null;
    const av = this.input.aimVector();
    if (av.active) return { x: p.x + av.x * 420, y: p.y + av.y * 420 };
    if (this.input.mouse.active && this.input.mouse.inside) {
      return { x: this.input.mouse.x + this.camera.x, y: this.input.mouse.y + this.camera.y };
    }
    return null;
  }

  updatePlayer(dt) {
    const p = this.player;
    const mv = this.input.moveVector();
    const moving = mv.len > 0.12;
    p.moving = moving;

    if (p.triple > 0) p.triple -= dt;
    if (p.rapid > 0) p.rapid -= dt;
    if (p.shield > 0) p.shield -= dt;

    if (this.input.takeDash()) this.tryDash(mv);

    if (p.dashTime > 0) {
      p.dashTime -= dt;
      p.x += p.dashVX * dt;
      p.y += p.dashVY * dt;
      p.bubbleT -= dt;
      if (p.bubbleT <= 0) {
        p.bubbleT = 0.025;
        this.addBubble(p.x - p.dashVX * 0.02, p.y - p.dashVY * 0.02, rnd(2, 5), 0.5);
      }
    } else {
      const speed = 342;
      const k = 1 - Math.exp(-9 * dt);
      p.vx = lerp(p.vx, mv.x * speed, k);
      p.vy = lerp(p.vy, mv.y * speed, k);
      p.x += p.vx * dt;
      p.y += p.vy * dt;
    }

    p.x = clamp(p.x, 64, WORLD.w - 64);
    p.y = clamp(p.y, 78, FLOOR - 24);

    if (moving) {
      p.angle = angleLerp(p.angle, Math.atan2(mv.y, mv.x), 1 - Math.exp(-12 * dt));
      if (Math.hypot(p.vx, p.vy) > 120) {
        p.bubbleT -= dt;
        if (p.bubbleT <= 0) {
          p.bubbleT = rnd(0.08, 0.16);
          this.addBubble(p.x - Math.cos(p.angle) * 20, p.y - Math.sin(p.angle) * 14, rnd(1.5, 3.5), 0.4);
        }
      }
    }

    if (this.aimPoint) {
      p.aimAngle = angleLerp(
        p.aimAngle,
        Math.atan2(this.aimPoint.y - p.y, this.aimPoint.x - p.x),
        1 - Math.exp(-22 * dt),
      );
    } else if (moving) {
      p.aimAngle = angleLerp(p.aimAngle, p.angle, 1 - Math.exp(-6 * dt));
    }
  }

  tryDash(mv) {
    const p = this.player;
    if (p.dashCd > 0 || p.dashTime > 0) return;
    let dx = mv.x;
    let dy = mv.y;
    if (Math.hypot(dx, dy) < 0.15) {
      dx = Math.cos(p.aimAngle);
      dy = Math.sin(p.aimAngle);
    }
    const l = Math.hypot(dx, dy) || 1;
    dx /= l;
    dy /= l;
    p.dashTime = 0.17;
    p.dashVX = dx * 1040;
    p.dashVY = dy * 1040;
    p.dashCd = p.dashMax;
    p.invuln = Math.max(p.invuln, 0.32);
    p.vx = p.dashVX * 0.5;
    p.vy = p.dashVY * 0.5;
    this.audio.dash();
    this.shake = Math.max(this.shake, 3);
    this.rings.push({ x: p.x, y: p.y, r: 12, max: 52, life: 0.35, t: 0, color: C.cyanSoft, width: 2 });
    for (let i = 0; i < 10; i++) {
      const a = Math.atan2(dy, dx) + Math.PI + rnd(-0.7, 0.7);
      this.addBubble(p.x + Math.cos(a) * rnd(4, 22), p.y + Math.sin(a) * rnd(4, 22), rnd(2, 6), rnd(0.3, 0.6));
    }
  }

  updateFiring(dt) {
    const p = this.player;
    if (p.reloading > 0) {
      p.reloading -= dt;
      if (p.reloading <= 0) {
        p.reloading = 0;
        p.ammo = p.mag;
      }
    }

    if (this.input.shooting() && !p.dead) {
      if (p.reloading <= 0) {
        if (p.ammo > 0) {
          if (p.fireCd <= 0) this.fire();
        } else {
          this.startReload();
        }
      }
    }
  }

  fire() {
    const p = this.player;
    const spread = p.triple > 0 ? [-0.125, 0, 0.125] : [0];
    const speed = 1120;
    p.ammo--;
    p.fireCd = p.rapid > 0 ? 0.072 : 0.135;
    p.recoil = 1;
    p.muzzle = 0.075;
    p.vx -= Math.cos(p.aimAngle) * 16;
    p.vy -= Math.sin(p.aimAngle) * 16;
    for (const off of spread) {
      const a = p.aimAngle + off + rnd(-0.012, 0.012);
      const mx = p.x + Math.cos(p.aimAngle) * 48;
      const my = p.y + Math.sin(p.aimAngle) * 48;
      this.bullets.push({
        x: mx, y: my, px: mx, py: my,
        vx: Math.cos(a) * speed, vy: Math.sin(a) * speed,
        life: 1.12, dmg: 13, dead: false, radius: 3,
      });
      this.particles.push({
        x: mx, y: my, vx: Math.cos(a) * rnd(40, 130) + rnd(-30, 30),
        vy: Math.sin(a) * rnd(40, 130) + rnd(-30, 30),
        life: rnd(0.08, 0.2), max: 0.2, size: rnd(1.5, 3.5),
        color: C.amber, type: 'spark', drag: 0.9,
      });
    }
    this.audio.shoot();
    this.shake = Math.max(this.shake, 1.3);
    if (p.ammo <= 0) this.startReload();
  }

  startReload() {
    const p = this.player;
    if (p.reloading > 0 || p.ammo >= p.mag) return;
    p.reloading = RELOAD_TIME;
    this.audio.reload();
  }

  /* ------------------------------------------------------------------ */
  /*  bullets                                                            */
  /* ------------------------------------------------------------------ */

  updateBullets(dt) {
    for (const b of this.bullets) {
      b.px = b.x;
      b.py = b.y;
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life -= dt;
      if (b.life <= 0 || b.x < 0 || b.y < 0 || b.x > WORLD.w || b.y > WORLD.h) {
        b.dead = true;
        continue;
      }
      for (const e of this.enemies) {
        if (e.dead || e.spawn < 0.35) continue;
        if (pointSegmentDistance(e.x, e.y, b.px, b.py, b.x, b.y) < e.radius + 4) {
          this.hitEnemy(e, b.dmg, b);
          b.dead = true;
          break;
        }
      }
    }
    this.bullets = this.bullets.filter((b) => !b.dead);
  }

  updateEnemyBullets(dt) {
    const p = this.player;
    for (const b of this.ebullets) {
      b.px = b.x;
      b.py = b.y;
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life -= dt;
      b.t += dt;
      if (b.life <= 0 || b.x < -50 || b.y < -50 || b.x > WORLD.w + 50 || b.y > WORLD.h + 50) {
        b.dead = true;
        continue;
      }
      if (!p.dead && p.dashTime <= 0 && pointSegmentDistance(p.x, p.y, b.px, b.py, b.x, b.y) < p.radius + b.radius) {
        this.damagePlayer(b.dmg, b.x, b.y);
        this.burst(b.x, b.y, b.color, 8, 140, 3);
        b.dead = true;
      }
    }
    this.ebullets = this.ebullets.filter((b) => !b.dead);
  }

  hitEnemy(e, dmg, b) {
    e.hp -= dmg;
    e.flash = 1;
    if (b) {
      e.vx += b.vx * 0.02;
      e.vy += b.vy * 0.02;
    }
    this.audio.hit();
    this.burst(b ? b.x : e.x, b ? b.y : e.y, e.type === 'boss' ? C.violet : C.amber, 4, 110, 2.5);
    if (e.type === 'boss') this.shake = Math.max(this.shake, 2.2);
    if (e.hp <= 0) this.killEnemy(e);
  }

  killEnemy(e) {
    if (e.dead) return;
    e.dead = true;
    this.kills++;
    this.combo++;
    this.comboTimer = 3.4;
    this.bestCombo = Math.max(this.bestCombo, this.combo);
    const mult = this.comboMult();
    const def = ENEMY_DEFS[e.type];
    const pts = Math.round(def.score * mult);
    this.score += pts;
    this.addText(e.x, e.y - e.radius - 6, `+${pts}`, this.combo > 1 ? C.amber : C.white, 16);

    if (e.type === 'boss') {
      this.boss = null;
      this.audio.explosion(true);
      this.shake = Math.max(this.shake, 26);
      this.burst(e.x, e.y, C.violet, 60, 420, 6);
      this.burst(e.x, e.y, C.amber, 30, 300, 4);
      this.ring(e.x, e.y, C.violet, 240, 0.9, 6);
      this.addText(e.x, e.y - 80, 'ANGLER SLAIN', C.violet, 26);
      for (let i = 0; i < 8; i++) {
        this.spawnPickup(e.x + rnd(-90, 90), e.y + rnd(-70, 70), i === 0 ? 'heart' : this.rollPickup(true));
      }
    } else {
      this.audio.explosion(e.type === 'shark');
      this.shake = Math.max(this.shake, e.type === 'shark' ? 8 : 3);
      this.burst(e.x, e.y, def.color, e.type === 'shark' ? 26 : 13, e.type === 'shark' ? 260 : 160, e.type === 'shark' ? 4.5 : 3);
      this.dropLoot(e);
    }
    if (this.combo === 5 || this.combo === 10 || this.combo === 20) {
      this.addText(this.player.x, this.player.y - 48, `${this.combo} COMBO!`, C.pink, 20);
    }
  }

  comboMult() {
    return Math.min(5, 1 + this.combo * 0.09);
  }

  /* ------------------------------------------------------------------ */
  /*  enemies                                                            */
  /* ------------------------------------------------------------------ */

  spawnEnemy(type, atX, atY) {
    if (this.enemies.length > 46) return;
    const p = this.player;
    let x = atX;
    let y = atY;
    if (x === undefined) {
      const minD = type === 'boss' ? 470 : Math.max(430, Math.min(this.w, this.h) * 0.58);
      const maxD = type === 'boss' ? 620 : Math.max(minD + 230, 820);
      let tries = 0;
      do {
        const a = rnd(0, TAU);
        const d = rnd(minD, maxD);
        x = clamp(p.x + Math.cos(a) * d, 90, WORLD.w - 90);
        y = clamp(p.y + Math.sin(a) * d, 110, FLOOR - 40);
        tries++;
      } while (Math.hypot(x - p.x, y - p.y) < 330 && tries < 14);
    }
    const def = ENEMY_DEFS[type];
    const scale = type === 'boss'
      ? 1 + Math.floor(this.wave / 5 - 1) * 0.55
      : 1 + (this.wave - 1) * 0.115;
    const hp = Math.round(def.hp * scale);
    const e = {
      type,
      x, y, vx: 0, vy: 0,
      radius: def.radius * (type === 'boss' ? 1 : rnd(0.92, 1.1)),
      hp, maxHp: hp,
      angle: rnd(0, TAU),
      t: rnd(0, 20),
      seed: rnd(0, 100),
      age: 0,
      spawn: 0,
      flash: 0,
      contactCd: 0,
      state: 'idle',
      stateT: 0,
      fireT: rnd(1.4, 2.6),
      burstT: 2.2,
      summonT: 5.5,
      chargeT: 7,
      modeT: 0,
      mode: 'drift',
      chargeVX: 0,
      chargeVY: 0,
      dead: false,
    };
    this.enemies.push(e);
    if (type === 'boss') {
      this.boss = e;
      this.audio.bossRoar();
      this.showBanner('ANGLERFISH', 'THE ABYSS STIRS', C.violet, 2.6);
      this.shake = Math.max(this.shake, 10);
    }
    this.ring(x, y, type === 'boss' ? C.violet : C.cyan, type === 'boss' ? 120 : 42, 0.5, 2);
    return e;
  }

  updateEnemies(dt) {
    const p = this.player;
    for (const e of this.enemies) {
      if (e.dead) continue;
      e.age += dt;
      e.t += dt;
      e.spawn = Math.min(1, e.spawn + dt * 3.2);
      e.flash = Math.max(0, e.flash - dt * 6);
      e.contactCd = Math.max(0, e.contactCd - dt);
      const dx = p.x - e.x;
      const dy = p.y - e.y;
      const d = Math.hypot(dx, dy) || 1;
      const toPlayer = Math.atan2(dy, dx);

      if (e.type === 'chomper') {
        const wobble = Math.sin(e.t * 3.1 + e.seed) * 0.42;
        const speed = ENEMY_DEFS.chomper.speed * (d < 240 ? 1.35 : 1) * (1 + this.wave * 0.012);
        const a = toPlayer + wobble;
        e.vx = lerp(e.vx, Math.cos(a) * speed, 1 - Math.exp(-2.4 * dt));
        e.vy = lerp(e.vy, Math.sin(a) * speed, 1 - Math.exp(-2.4 * dt));
      } else if (e.type === 'puffer') {
        let a = toPlayer;
        let speed = ENEMY_DEFS.puffer.speed;
        if (d < 190) { a = toPlayer + Math.PI; speed *= 1.25; }
        else if (d < 300) { a = toPlayer + Math.PI / 2; speed *= 0.85; }
        e.vx = lerp(e.vx, Math.cos(a) * speed, 1 - Math.exp(-1.8 * dt));
        e.vy = lerp(e.vy, Math.sin(a) * speed, 1 - Math.exp(-1.8 * dt));
        e.fireT -= dt;
        if (e.fireT <= 0) {
          e.fireT = rnd(2.3, 2.9);
          this.enemyRadial(e, 7, 195, 10, C.amber, 0.22);
        }
      } else if (e.type === 'jelly') {
        const a = toPlayer + Math.sin(e.t * 1.4 + e.seed) * 0.9;
        e.vx = lerp(e.vx, Math.cos(a) * ENEMY_DEFS.jelly.speed, 1 - Math.exp(-1.2 * dt));
        e.vy = lerp(e.vy, Math.sin(a) * ENEMY_DEFS.jelly.speed, 1 - Math.exp(-1.2 * dt));
        e.fireT -= dt;
        if (e.fireT <= 0) {
          e.fireT = rnd(3.2, 4.2);
          this.enemyRadial(e, 6, 130, 11, C.violet, 0.5);
          this.ring(e.x, e.y, C.violet, 80, 0.5, 2);
        }
      } else if (e.type === 'shark') {
        if (e.state === 'idle') {
          const a = toPlayer + Math.sin(e.t * 0.8) * 0.8;
          const speed = ENEMY_DEFS.shark.speed * 0.75;
          e.vx = lerp(e.vx, Math.cos(a) * speed, 1 - Math.exp(-2 * dt));
          e.vy = lerp(e.vy, Math.sin(a) * speed, 1 - Math.exp(-2 * dt));
          e.stateT += dt;
          if (e.stateT > 2.1 && d < 560) { e.state = 'wind'; e.stateT = 0; }
        } else if (e.state === 'wind') {
          e.vx *= Math.pow(0.02, dt);
          e.vy *= Math.pow(0.02, dt);
          e.stateT += dt;
          if (e.stateT > 0.65) {
            e.state = 'charge';
            e.stateT = 0;
            e.chargeVX = Math.cos(toPlayer) * 660;
            e.chargeVY = Math.sin(toPlayer) * 660;
            this.audio.enemyShoot();
          }
        } else {
          e.vx = e.chargeVX;
          e.vy = e.chargeVY;
          e.stateT += dt;
          if (e.stateT > 0.8) { e.state = 'idle'; e.stateT = 0; }
        }
      } else if (e.type === 'boss') {
        this.updateBoss(e, dt, d, toPlayer);
      }

      e.x += e.vx * dt;
      e.y += e.vy * dt;
      if (e.state !== 'charge' || e.type === 'boss') {
        e.angle = angleLerp(e.angle, Math.atan2(e.vy, e.vx) || e.angle, 1 - Math.exp(-4 * dt));
      } else {
        e.angle = angleLerp(e.angle, toPlayer, 1 - Math.exp(-8 * dt));
      }
      const pad = e.radius + 20;
      if (e.x < pad) { e.x = pad; e.vx = Math.abs(e.vx) * 0.6; }
      if (e.x > WORLD.w - pad) { e.x = WORLD.w - pad; e.vx = -Math.abs(e.vx) * 0.6; }
      if (e.y < 60 + e.radius) { e.y = 60 + e.radius; e.vy = Math.abs(e.vy) * 0.6; }
      if (e.y > FLOOR - e.radius * 0.5) { e.y = FLOOR - e.radius * 0.5; e.vy = -Math.abs(e.vy) * 0.6; }

      if (e.spawn > 0.55 && e.contactCd <= 0 && !p.dead) {
        if (Math.hypot(p.x - e.x, p.y - e.y) < p.radius + e.radius * 0.85) {
          e.contactCd = 0.9;
          this.damagePlayer(ENEMY_DEFS[e.type].contact, e.x, e.y);
          const a = Math.atan2(p.y - e.y, p.x - e.x);
          p.vx += Math.cos(a) * 340;
          p.vy += Math.sin(a) * 340;
        }
      }
    }

    // Soft separation so the school doesn't stack into one blob.
    for (let i = 0; i < this.enemies.length; i++) {
      const a = this.enemies[i];
      if (a.dead) continue;
      for (let j = i + 1; j < this.enemies.length; j++) {
        const b = this.enemies[j];
        if (b.dead) continue;
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const min = a.radius + b.radius;
        const d2 = dx * dx + dy * dy;
        if (d2 > 0 && d2 < min * min) {
          const d = Math.sqrt(d2);
          const push = ((min - d) / d) * 0.5;
          const ax = a.type === 'boss' ? 0.1 : 1;
          const bx = b.type === 'boss' ? 0.1 : 1;
          a.x -= dx * push * ax;
          a.y -= dy * push * ax;
          b.x += dx * push * bx;
          b.y += dy * push * bx;
        }
      }
    }

    this.enemies = this.enemies.filter((e) => !e.dead);
  }

  updateBoss(e, dt, d, toPlayer) {
    const p = this.player;
    const orbit = toPlayer + Math.PI / 2;
    let speed = ENEMY_DEFS.boss.speed;
    let moveA = toPlayer;
    if (d < 250) { moveA = toPlayer + Math.PI; speed *= 1.2; }
    else if (d < 380) { moveA = orbit; speed *= 0.9; }
    e.vx = lerp(e.vx, Math.cos(moveA) * speed, 1 - Math.exp(-1.4 * dt));
    e.vy = lerp(e.vy, Math.sin(moveA) * speed, 1 - Math.exp(-1.4 * dt));

    e.burstT -= dt;
    e.summonT -= dt;
    e.chargeT -= dt;

    if (e.mode === 'charge') {
      e.modeT -= dt;
      e.vx = e.chargeVX;
      e.vy = e.chargeVY;
      e.bubbleT = (e.bubbleT || 0) - dt;
      if (e.bubbleT <= 0) {
        e.bubbleT = 0.05;
        this.addBubble(e.x, e.y, rnd(3, 7), 0.5);
      }
      if (e.modeT <= 0) e.mode = 'drift';
    } else if (e.chargeT <= 0 && d < 560) {
      e.chargeT = rnd(7.5, 9.5);
      e.mode = 'charge';
      e.modeT = 0.95;
      e.chargeVX = Math.cos(toPlayer) * 560;
      e.chargeVY = Math.sin(toPlayer) * 560;
      this.audio.bossRoar();
      this.ring(e.x, e.y, C.pink, 160, 0.5, 3);
    }

    if (e.burstT <= 0) {
      e.burstT = 2.15;
      this.enemyRadial(e, 12, 210, 12, C.violet, rnd(0, TAU));
      this.ring(e.x, e.y, C.violet, 150, 0.5, 3);
      this.audio.enemyShoot();
    }
    if (e.summonT <= 0) {
      e.summonT = 7.5;
      if (this.enemies.length < 26) {
        for (let i = 0; i < 2; i++) {
          const a = rnd(0, TAU);
          this.spawnEnemy('chomper', clamp(e.x + Math.cos(a) * 90, 90, WORLD.w - 90), clamp(e.y + Math.sin(a) * 90, 90, FLOOR - 40));
        }
        this.ring(e.x, e.y, C.orange, 110, 0.5, 3);
      }
    }
  }

  enemyRadial(e, count, speed, dmg, color, offset = 0) {
    for (let i = 0; i < count; i++) {
      const a = offset + (i / count) * TAU;
      this.ebullets.push({
        x: e.x + Math.cos(a) * (e.radius + 6),
        y: e.y + Math.sin(a) * (e.radius + 6),
        px: e.x,
        py: e.y,
        vx: Math.cos(a) * speed,
        vy: Math.sin(a) * speed,
        radius: e.type === 'boss' ? 8 : 6,
        dmg,
        life: 4.2,
        t: 0,
        color,
        dead: false,
        kind: e.type === 'boss' ? 'orb' : e.type === 'jelly' ? 'glow' : 'spine',
      });
    }
    e.flash = Math.max(e.flash, 0.5);
  }

  /* ------------------------------------------------------------------ */
  /*  pickups / damage                                                   */
  /* ------------------------------------------------------------------ */

  dropLoot(e) {
    const def = ENEMY_DEFS[e.type];
    let chance = def.drop;
    if (this.player.hp < 40) chance += 0.1;
    if (Math.random() > chance) return;
    this.spawnPickup(e.x, e.y, this.rollPickup(false));
  }

  rollPickup(rich = false) {
    const r = Math.random();
    if (this.player.hp < 55 && r < (rich ? 0.4 : 0.34)) return 'heart';
    if (r < 0.5) return 'pearl';
    if (r < 0.7) return 'heart';
    if (r < 0.82) return 'triple';
    if (r < 0.93) return 'rapid';
    return 'shield';
  }

  spawnPickup(x, y, type) {
    this.pickups.push({
      x: clamp(x, 60, WORLD.w - 60),
      y: clamp(y, 80, FLOOR - 30),
      vx: rnd(-60, 60),
      vy: rnd(-80, -20),
      type,
      t: rnd(0, 10),
      life: 14,
      r: 12,
      dead: false,
    });
    this.ring(x, y, PICKUP_DEFS[type].color, 34, 0.45, 2);
  }

  updatePickups(dt) {
    const p = this.player;
    for (const it of this.pickups) {
      it.t += dt;
      it.life -= dt;
      const dx = p.x - it.x;
      const dy = p.y - it.y;
      const d = Math.hypot(dx, dy) || 1;
      if (d < 150) {
        const pull = (1 - d / 150) * 900;
        it.vx += (dx / d) * pull * dt;
        it.vy += (dy / d) * pull * dt;
      }
      it.vx *= Math.pow(0.25, dt);
      it.vy *= Math.pow(0.25, dt);
      it.x += it.vx * dt;
      it.y += it.vy * dt;
      it.x = clamp(it.x, 40, WORLD.w - 40);
      it.y = clamp(it.y, 60, FLOOR - 20);
      if (d < 28) {
        this.collectPickup(it);
        it.dead = true;
      }
      if (it.life <= 0) it.dead = true;
    }
    this.pickups = this.pickups.filter((it) => !it.dead);
  }

  collectPickup(it) {
    const p = this.player;
    const color = PICKUP_DEFS[it.type].color;
    this.burst(it.x, it.y, color, 8, 120, 2.5);
    this.addText(it.x, it.y - 18, PICKUP_DEFS[it.type].label, color, 13);
    if (it.type === 'pearl') {
      this.score += Math.round(60 * this.comboMult());
      this.audio.pickup(1);
    } else if (it.type === 'heart') {
      p.hp = Math.min(p.maxHp, p.hp + 22);
      this.audio.pickup(2);
    } else if (it.type === 'triple') {
      p.triple = Math.max(p.triple, 10);
      this.audio.powerup();
    } else if (it.type === 'rapid') {
      p.rapid = Math.max(p.rapid, 10);
      this.audio.powerup();
    } else if (it.type === 'shield') {
      p.shield = Math.max(p.shield, 12);
      this.audio.powerup();
    }
    this.ring(it.x, it.y, color, 36, 0.4, 2);
  }

  damagePlayer(dmg, sx, sy) {
    const p = this.player;
    if (p.dead || p.invuln > 0 || p.dashTime > 0) return;
    if (p.shield > 0) {
      p.shield = 0;
      p.invuln = Math.max(p.invuln, 0.7);
      this.audio.shieldBreak();
      this.audio.hurt();
      this.ring(p.x, p.y, C.cyan, 70, 0.5, 4);
      this.burst(p.x, p.y, C.cyan, 18, 220, 3);
      this.addText(p.x, p.y - 40, 'SHIELD BROKEN', C.cyan, 15);
      this.shake = Math.max(this.shake, 8);
      return;
    }
    p.hp -= dmg;
    p.invuln = 0.85;
    p.hitT = 1;
    this.combo = 0;
    this.comboTimer = 0;
    this.hurtFlash = 1;
    this.shake = Math.max(this.shake, 13);
    this.audio.hurt();
    const a = Math.atan2(p.y - sy, p.x - sx) || 0;
    p.vx += Math.cos(a) * 260;
    p.vy += Math.sin(a) * 260;
    this.burst(p.x, p.y, C.pink, 14, 190, 3.5);
    this.addText(p.x, p.y - 34, `-${Math.round(dmg)}`, C.pink, 17);
    if (p.hp <= 0) {
      p.hp = 0;
      this.die();
    }
  }

  die() {
    const p = this.player;
    p.dead = true;
    this.state = 'dying';
    this.input.enabled = false;
    this.input.releaseAll();
    this.shake = 32;
    this.hurtFlash = 1;
    this.audio.explosion(true);
    this.audio.hurt();
    this.burst(p.x, p.y, C.orange, 60, 440, 6);
    this.burst(p.x, p.y, C.amber, 30, 300, 4);
    this.ring(p.x, p.y, C.orange, 200, 0.9, 6);
    this.enemies.forEach((e) => { e.vx *= 0.2; e.vy *= 0.2; });

    const isBest = this.score > this.best;
    if (isBest) {
      this.best = Math.round(this.score);
      saveBest(this.best);
    }
    const stats = {
      score: Math.round(this.score),
      kills: this.kills,
      wave: this.wave,
      best: this.best,
      bestCombo: this.bestCombo,
      isBest,
    };
    const token = this.runToken;
    this.emit('dying');
    setTimeout(() => {
      if (this.runToken !== token || this.state !== 'dying') return;
      this.state = 'gameover';
      this.emit('gameover', stats);
    }, 850);
  }

  /* ------------------------------------------------------------------ */
  /*  waves                                                              */
  /* ------------------------------------------------------------------ */

  buildWave(n) {
    const q = [];
    if (n % 5 === 0) {
      q.push({ type: 'boss', at: this.t + 1.4 });
      const adds = 2 + Math.floor(n / 5);
      for (let i = 0; i < adds; i++) q.push({ type: 'chomper', at: this.t + 2.5 + i * 0.8 });
      this.lastWaveHadBoss = true;
      return q;
    }
    this.lastWaveHadBoss = false;
    const chompers = Math.min(22, 3 + Math.floor(n * 1.7));
    const puffers = n >= 2 ? Math.min(7, Math.floor(n / 2)) : 0;
    const jellies = n >= 3 ? Math.min(6, Math.floor(n / 3)) : 0;
    const sharks = n >= 4 ? Math.min(4, Math.floor((n - 1) / 3)) : 0;
    const all = [];
    for (let i = 0; i < chompers; i++) all.push('chomper');
    for (let i = 0; i < puffers; i++) all.push('puffer');
    for (let i = 0; i < jellies; i++) all.push('jelly');
    for (let i = 0; i < sharks; i++) all.push('shark');
    // Shuffle so each wave feels mixed.
    for (let i = all.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [all[i], all[j]] = [all[j], all[i]];
    }
    const gap = Math.max(0.34, 0.95 - n * 0.035);
    all.forEach((type, i) => {
      q.push({ type, at: this.t + 1.9 + i * gap + rnd(0, 0.25) });
    });
    return q;
  }

  startWave(n) {
    this.wave = n;
    this.waveState = 'fighting';
    this.spawnQueue = this.buildWave(n);
    const boss = n % 5 === 0;
    const title = boss ? 'ANGLERFISH' : `WAVE ${String(n).padStart(2, '0')}`;
    const sub = boss ? 'THE ABYSS STIRS' : WAVE_TAGS[(n - 1) % WAVE_TAGS.length];
    this.showBanner(title, sub, boss ? C.violet : C.amber, 2.5);
    if (!boss) this.audio.waveStart();
  }

  updateWave(dt) {
    if (this.waveState === 'fighting') {
      if (this.spawnQueue.length === 0 && this.enemies.length === 0) {
        this.waveState = 'cleared';
        this.clearTimer = 3;
        const bonus = 75 * this.wave;
        this.score += bonus;
        const p = this.player;
        p.hp = Math.min(p.maxHp, p.hp + 12);
        p.ammo = p.mag;
        p.reloading = 0;
        this.showBanner(
          this.lastWaveHadBoss ? 'ANGLER SLAIN' : 'WAVE CLEARED',
          `+${bonus} BONUS · +12 HP · AMMO REFILLED`,
          this.lastWaveHadBoss ? C.violet : C.green,
          2.5,
        );
        this.audio.waveClear();
      }
    } else if (this.waveState === 'cleared') {
      this.clearTimer -= dt;
      if (this.clearTimer <= 0) this.startWave(this.wave + 1);
    }
  }

  /* ------------------------------------------------------------------ */
  /*  effects / camera / ambient                                         */
  /* ------------------------------------------------------------------ */

  showBanner(title, sub, color, dur = 2.2) {
    this.banner = { title, sub, color, t: 0, dur };
  }

  addText(x, y, text, color, size = 15) {
    this.texts.push({ x, y, text, color, size, life: 0.9, max: 0.9, vy: -38 });
    if (this.texts.length > 40) this.texts.shift();
  }

  burst(x, y, color, count, speed, size = 3) {
    for (let i = 0; i < count; i++) {
      const a = rnd(0, TAU);
      const s = rnd(speed * 0.25, speed);
      this.particles.push({
        x, y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s,
        life: rnd(0.3, 0.85),
        max: 0.85,
        size: rnd(size * 0.5, size),
        color,
        type: Math.random() < 0.28 ? 'bubble' : 'spark',
        drag: 0.86,
      });
    }
    if (this.particles.length > 700) this.particles.splice(0, this.particles.length - 700);
  }

  addBubble(x, y, size = 3, life = 0.6) {
    this.particles.push({
      x, y,
      vx: rnd(-14, 14),
      vy: rnd(-34, -8),
      life: rnd(life * 0.6, life * 1.4),
      max: life * 1.4,
      size,
      color: C.cyanSoft,
      type: 'bubble',
      drag: 0.97,
    });
    if (this.particles.length > 700) this.particles.shift();
  }

  ring(x, y, color, max, life = 0.5, width = 2) {
    this.rings.push({ x, y, r: 6, max, life, t: 0, color, width });
    if (this.rings.length > 30) this.rings.shift();
  }

  updateEffects(dt) {
    this.shake *= Math.exp(-7.5 * dt);
    if (this.shake < 0.05) this.shake = 0;
    this.hurtFlash = Math.max(0, this.hurtFlash - dt * 1.8);

    if (this.banner) {
      this.banner.t += dt;
      if (this.banner.t > this.banner.dur) this.banner = null;
    }

    for (const pt of this.particles) {
      pt.life -= dt;
      const drag = Math.pow(pt.drag, dt * 60);
      pt.vx *= drag;
      pt.vy *= drag;
      if (pt.type === 'bubble') pt.vy -= 16 * dt;
      pt.x += pt.vx * dt;
      pt.y += pt.vy * dt;
    }
    this.particles = this.particles.filter((pt) => pt.life > 0);

    for (const tx of this.texts) {
      tx.life -= dt;
      tx.y += tx.vy * dt;
      tx.vy *= Math.pow(0.9, dt * 60);
    }
    this.texts = this.texts.filter((tx) => tx.life > 0);

    for (const r of this.rings) {
      r.t += dt;
      const k = clamp(r.t / r.life, 0, 1);
      r.r = lerp(6, r.max, easeOut(k));
    }
    this.rings = this.rings.filter((r) => r.t < r.life);
  }

  updateCamera(dt) {
    const p = this.player;
    let lookX = 0;
    let lookY = 0;
    if (this.aimPoint) {
      lookX = clamp((this.aimPoint.x - p.x) * 0.16, -95, 95);
      lookY = clamp((this.aimPoint.y - p.y) * 0.16, -80, 80);
    }
    const tx = clamp(p.x + lookX - this.w / 2, 0, Math.max(0, WORLD.w - this.w));
    const ty = clamp(p.y + lookY - this.h / 2, 0, Math.max(0, WORLD.h - this.h));
    const k = 1 - Math.exp(-6.5 * dt);
    this.camera.x = lerp(this.camera.x, tx, k);
    this.camera.y = lerp(this.camera.y, ty, k);
    this.clampCamera(false);
  }

  clampCamera(snap = false) {
    if (!this.camera) return;
    const maxX = Math.max(0, WORLD.w - this.w);
    const maxY = Math.max(0, WORLD.h - this.h);
    const tx = this.w > WORLD.w ? (WORLD.w - this.w) / 2 : clamp(this.camera.x, 0, maxX);
    const ty = this.h > WORLD.h ? (WORLD.h - this.h) / 2 : clamp(this.camera.y, 0, maxY);
    if (snap) {
      this.camera.x = tx;
      this.camera.y = ty;
    } else {
      this.camera.x = clamp(this.camera.x, 0, maxX);
      this.camera.y = clamp(this.camera.y, 0, maxY);
    }
  }

  updateAmbient(dt) {
    const a = this.ambient;
    if (!a) return;
    for (const b of a.bubbles) {
      b.y -= b.speed * dt;
      b.x += Math.sin(this.t * 0.8 + b.phase) * 8 * dt;
      if (b.y < -20) {
        b.y = WORLD.h + rnd(0, 80);
        b.x = rnd(0, WORLD.w);
      }
    }
    for (const m of a.motes) {
      m.y -= m.speed * dt;
      m.x += Math.sin(this.t * 0.5 + m.phase) * 4 * dt;
      if (m.y < 0) {
        m.y = WORLD.h;
        m.x = rnd(0, WORLD.w);
      }
    }
    for (const f of a.bgFish) {
      f.nx += f.dir * f.speed * dt;
      if (f.nx > this.w + 220) f.nx = -180;
      if (f.nx < -220) f.nx = this.w + 180;
    }
    a.bubbleT -= dt;
    if (a.bubbleT <= 0) {
      a.bubbleT = rnd(4, 9);
      if (this.audio.available) this.audio.bubble();
    }
  }
}

import {
  TAU, WORLD, FLOOR, C, FONT, DISPLAY, PICKUP_DEFS,
  clamp, lerp, mod, rnd, roundRect, formatNumber,
} from './core.js';
import { drawHUD, drawTouchControls } from './hud.js';

export class Renderer {
  constructor(game) {
    this.game = game;
    this.ctx = game.ctx;
    this.decor = this.makeDecor();
    this.bgGrad = null;
    this.vignette = null;
    this.aimHover = null;
  }

  resize() {
    const { ctx, w, h } = this.game;
    this.bgGrad = ctx.createLinearGradient(0, 0, 0, h);
    this.bgGrad.addColorStop(0, '#0b3a4c');
    this.bgGrad.addColorStop(0.32, '#072838');
    this.bgGrad.addColorStop(0.7, '#04151f');
    this.bgGrad.addColorStop(1, '#01070c');
    this.vignette = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.3, w / 2, h / 2, Math.max(w, h) * 0.78);
    this.vignette.addColorStop(0, 'rgba(0,0,0,0)');
    this.vignette.addColorStop(0.72, 'rgba(0,4,8,0.12)');
    this.vignette.addColorStop(1, 'rgba(0,4,8,0.6)');
  }

  makeDecor() {
    const weeds = [];
    const rocks = [];
    const corals = [];
    for (let i = 0; i < 100; i++) {
      weeds.push({
        x: rnd(0, WORLD.w),
        y: FLOOR + rnd(-4, 46),
        h: rnd(45, 185),
        phase: rnd(0, TAU),
        lean: rnd(-0.4, 0.4),
        hue: Math.random() < 0.5 ? '#1f6b5c' : Math.random() < 0.5 ? '#2c7d63' : '#176052',
        blades: Array.from({ length: 3 }, (_, j) => ({
          o: rnd(-12, 12),
          hk: rnd(0.6, 1),
          w: rnd(1.5, 3.6),
          ph: rnd(0, TAU) + j,
        })),
      });
    }
    for (let i = 0; i < 55; i++) {
      rocks.push({
        x: rnd(0, WORLD.w),
        y: FLOOR + rnd(8, 66),
        w: rnd(22, 88),
        h: rnd(10, 34),
        rot: rnd(-0.2, 0.2),
        shade: Math.random() < 0.5 ? '#06141b' : '#081a22',
      });
    }
    const coralColors = ['#b14d63', '#c46a49', '#8a4d7c', '#3f7f78', '#a45b3f'];
    for (let i = 0; i < 34; i++) {
      corals.push({
        x: rnd(0, WORLD.w),
        y: FLOOR + rnd(0, 24),
        size: rnd(18, 62),
        phase: rnd(0, TAU),
        color: coralColors[Math.floor(rnd(0, coralColors.length))],
      });
    }
    return { weeds, rocks, corals };
  }

  /* ================================================================== */
  /*  main render                                                        */
  /* ================================================================== */

  render(game) {
    const ctx = game.ctx;
    ctx.setTransform(game.dpr, 0, 0, game.dpr, 0, 0);
    ctx.imageSmoothingEnabled = true;

    this.drawBackdrop(game);

    const shake = game.shake;
    const sx = shake ? rnd(-shake, shake) : 0;
    const sy = shake ? rnd(-shake, shake) : 0;

    ctx.save();
    ctx.translate(-game.camera.x + sx, -game.camera.y + sy);
    this.drawWorld(game);
    this.drawPickups(game);
    this.drawEnemyBullets(game);
    this.drawEnemies(game);
    if (game.state === 'playing' || game.state === 'paused') this.drawAimGuide(game);
    if (!game.player.dead) this.drawPlayer(game);
    this.drawBullets(game);
    this.drawRings(game);
    this.drawParticles(game);
    this.drawTexts(game);
    ctx.restore();

    this.drawScreenFX(game);

    if (game.state !== 'menu') {
      drawHUD(game);
      drawTouchControls(game);
      this.drawReticle(game);
    }
  }

  drawBackdrop(game) {
    const { ctx, w, h, t } = game;
    ctx.fillStyle = this.bgGrad || '#04151f';
    ctx.fillRect(0, 0, w, h);

    // Light shafts from the surface.
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 7; i++) {
      const phase = t * 0.045 + i * 1.71;
      const x = (i / 6) * w + Math.sin(phase) * w * 0.07;
      const topW = 34 + Math.sin(i * 2.3) * 18;
      const grad = ctx.createLinearGradient(0, 0, 0, h * 0.95);
      grad.addColorStop(0, 'rgba(130,245,255,0.075)');
      grad.addColorStop(0.7, 'rgba(90,200,230,0.022)');
      grad.addColorStop(1, 'rgba(60,150,190,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(x - topW / 2, -80);
      ctx.lineTo(x + topW / 2, -80);
      ctx.lineTo(x + topW / 2 + 190 + Math.sin(phase * 0.7) * 40, h * 0.95);
      ctx.lineTo(x - topW / 2 + 120 + Math.sin(phase * 0.7) * 40, h * 0.95);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    this.drawDistantFish(game);
  }

  drawDistantFish(game) {
    const { ctx, w, h, t, camera, ambient } = game;
    ctx.save();
    for (const f of ambient.bgFish) {
      const x = mod(f.nx - camera.x * 0.12, w + 300) - 150;
      const y = f.ny * h + Math.sin(t * 0.4 + f.phase) * 9;
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(f.scale * (f.dir < 0 ? -1 : 1), f.scale);
      ctx.globalAlpha = f.alpha;
      ctx.fillStyle = '#9ceef5';
      ctx.beginPath();
      ctx.ellipse(0, 0, 24, 8, 0, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-20, 0);
      ctx.quadraticCurveTo(-34, -9, -40, 0);
      ctx.quadraticCurveTo(-34, 9, -20, 0);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-2, -7);
      ctx.lineTo(8, -14);
      ctx.lineTo(13, -6);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  }

  drawWorld(game) {
    const { ctx, camera, t } = game;
    const x0 = camera.x - 140;
    const x1 = camera.x + game.w + 140;

    // Water surface.
    if (camera.y < 210) {
      const surf = ctx.createLinearGradient(0, -20, 0, 230);
      surf.addColorStop(0, 'rgba(150,255,255,0.20)');
      surf.addColorStop(0.35, 'rgba(80,210,235,0.06)');
      surf.addColorStop(1, 'rgba(20,80,110,0)');
      ctx.fillStyle = surf;
      ctx.fillRect(x0, -30, x1 - x0, 260);
      ctx.strokeStyle = 'rgba(185,255,255,0.38)';
      ctx.lineWidth = 2;
      for (let k = 0; k < 2; k++) {
        ctx.beginPath();
        for (let x = x0; x <= x1; x += 22) {
          const y = 28 + k * 15 + Math.sin(x * 0.012 + t * 1.6 + k * 1.4) * 6 + Math.sin(x * 0.026 - t * 1.1) * 3;
          if (x === x0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.globalAlpha = k === 0 ? 0.5 : 0.2;
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
    }

    // Sand floor.
    const floorGrad = ctx.createLinearGradient(0, FLOOR - 20, 0, WORLD.h);
    floorGrad.addColorStop(0, '#173c3b');
    floorGrad.addColorStop(0.22, '#0f2c30');
    floorGrad.addColorStop(1, '#050f14');
    ctx.fillStyle = floorGrad;
    ctx.beginPath();
    ctx.moveTo(x0, WORLD.h + 20);
    for (let x = x0; x <= x1; x += 34) {
      const y = FLOOR + Math.sin(x * 0.006) * 15 + Math.sin(x * 0.014 + 1.7) * 8 + Math.cos(x * 0.002) * 8;
      ctx.lineTo(x, y);
    }
    ctx.lineTo(x1, WORLD.h + 20);
    ctx.closePath();
    ctx.fill();

    // Dune shadow line.
    ctx.fillStyle = 'rgba(2,10,14,0.35)';
    ctx.beginPath();
    ctx.moveTo(x0, WORLD.h + 20);
    for (let x = x0; x <= x1; x += 40) {
      const y = FLOOR + 56 + Math.sin(x * 0.005 + 2) * 12 + Math.cos(x * 0.011) * 6;
      ctx.lineTo(x, y);
    }
    ctx.lineTo(x1, WORLD.h + 20);
    ctx.closePath();
    ctx.fill();

    // Rocks, weeds and coral (culled to view).
    for (const r of this.decor.rocks) {
      if (r.x < x0 - 120 || r.x > x1 + 120) continue;
      ctx.save();
      ctx.translate(r.x, r.y);
      ctx.rotate(r.rot);
      ctx.fillStyle = r.shade;
      ctx.beginPath();
      ctx.ellipse(0, 0, r.w, r.h, 0, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = 'rgba(70,140,150,0.07)';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.restore();
    }

    for (const wd of this.decor.weeds) {
      if (wd.x < x0 - 80 || wd.x > x1 + 80) continue;
      ctx.save();
      ctx.lineCap = 'round';
      ctx.strokeStyle = wd.hue;
      for (const b of wd.blades) {
        const sway = Math.sin(t * 1.05 + wd.phase + b.ph) * (8 + wd.h * 0.06);
        const top = wd.y - wd.h * b.hk;
        ctx.globalAlpha = 0.55;
        ctx.lineWidth = b.w;
        ctx.beginPath();
        ctx.moveTo(wd.x + b.o, wd.y);
        ctx.quadraticCurveTo(
          wd.x + b.o + wd.lean * 22 + sway * 0.4,
          wd.y - wd.h * b.hk * 0.55,
          wd.x + b.o + wd.lean * 34 + sway,
          top,
        );
        ctx.stroke();
      }
      ctx.restore();
    }

    for (const c of this.decor.corals) {
      if (c.x < x0 - 80 || c.x > x1 + 80) continue;
      const sway = Math.sin(t * 0.8 + c.phase) * 2;
      ctx.save();
      ctx.translate(c.x, c.y);
      ctx.strokeStyle = c.color;
      ctx.fillStyle = c.color;
      ctx.globalAlpha = 0.5;
      ctx.lineCap = 'round';
      ctx.lineWidth = Math.max(2, c.size * 0.08);
      for (let i = 0; i < 5; i++) {
        const a = -Math.PI / 2 + (i - 2) * 0.32 + sway * 0.01;
        const ex = Math.cos(a) * c.size;
        const ey = Math.sin(a) * c.size;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.quadraticCurveTo(ex * 0.3, ey * 0.55, ex, ey);
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(ex, ey, Math.max(2, c.size * 0.11), 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }

    // Ambient bubbles and motes.
    for (const b of game.ambient.bubbles) {
      if (b.x < x0 || b.x > x1 || b.y < camera.y - 40 || b.y > camera.y + game.h + 40) continue;
      ctx.globalAlpha = 0.16 + Math.min(0.18, b.r * 0.03);
      ctx.strokeStyle = '#bdf6ff';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, TAU);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    for (const m of game.ambient.motes) {
      if (m.x < x0 || m.x > x1 || m.y < camera.y - 40 || m.y > camera.y + game.h + 40) continue;
      ctx.globalAlpha = 0.1 + Math.sin(t * 1.2 + m.phase) * 0.05;
      ctx.fillStyle = '#d8ffff';
      ctx.beginPath();
      ctx.arc(m.x, m.y, m.r, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // World edge haze.
    const edge = ctx.createLinearGradient(x0, 0, x0 + 220, 0);
    edge.addColorStop(0, 'rgba(0,6,10,0.4)');
    edge.addColorStop(1, 'rgba(0,6,10,0)');
    ctx.fillStyle = edge;
    ctx.fillRect(x0, camera.y - 100, 220, game.h + 200);
    const edgeR = ctx.createLinearGradient(x1 - 220, 0, x1, 0);
    edgeR.addColorStop(0, 'rgba(0,6,10,0)');
    edgeR.addColorStop(1, 'rgba(0,6,10,0.4)');
    ctx.fillStyle = edgeR;
    ctx.fillRect(x1 - 220, camera.y - 100, 220, game.h + 200);
  }

  /* ================================================================== */
  /*  player                                                             */
  /* ================================================================== */

  drawPlayer(game) {
    const { ctx, t } = game;
    const p = game.player;
    const flicker = p.invuln > 0 && Math.floor(t * 24) % 2 === 0;
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.globalAlpha = flicker ? 0.55 : 1;

    if (p.shield > 0) {
      const pulse = 1 + Math.sin(t * 6) * 0.03;
      ctx.save();
      ctx.globalAlpha = 0.4 + Math.sin(t * 5) * 0.1;
      ctx.strokeStyle = C.cyan;
      ctx.lineWidth = 2;
      ctx.setLineDash([10, 7]);
      ctx.lineDashOffset = -t * 40;
      ctx.beginPath();
      ctx.arc(0, 0, 34 * pulse, 0, TAU);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = 0.08;
      ctx.fillStyle = C.cyan;
      ctx.beginPath();
      ctx.arc(0, 0, 34, 0, TAU);
      ctx.fill();
      ctx.restore();
    }

    // Tail + body face the swim direction.
    ctx.save();
    ctx.rotate(p.angle);
    const wag = Math.sin(t * (p.moving ? 16 : 6)) * 0.5;

    ctx.fillStyle = '#e8792f';
    ctx.beginPath();
    ctx.moveTo(-14, 0);
    ctx.quadraticCurveTo(-30, -10 - wag * 10, -47, -5 - wag * 6);
    ctx.quadraticCurveTo(-37, 0, -47, 5 - wag * 6);
    ctx.quadraticCurveTo(-30, 10 - wag * 10, -14, 0);
    ctx.fill();

    ctx.fillStyle = 'rgba(255,190,90,0.85)';
    ctx.beginPath();
    ctx.moveTo(-1, -13);
    ctx.quadraticCurveTo(4, -27, 15, -15);
    ctx.closePath();
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-3, 12);
    ctx.quadraticCurveTo(-10, 24, 8, 15);
    ctx.closePath();
    ctx.fill();

    const bodyGrad = ctx.createLinearGradient(-20, -15, 20, 15);
    bodyGrad.addColorStop(0, '#ffb45c');
    bodyGrad.addColorStop(0.55, '#ff9036');
    bodyGrad.addColorStop(1, '#e5602a');
    ctx.fillStyle = bodyGrad;
    ctx.beginPath();
    ctx.ellipse(0, 0, 23, 15.5, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(90,28,8,0.5)';
    ctx.lineWidth = 1.4;
    ctx.stroke();

    ctx.fillStyle = 'rgba(255,235,190,0.45)';
    ctx.beginPath();
    ctx.ellipse(2, 7, 14, 6, 0.05, 0, TAU);
    ctx.fill();

    ctx.strokeStyle = 'rgba(200,70,20,0.4)';
    ctx.lineWidth = 2;
    for (let i = 0; i < 2; i++) {
      ctx.beginPath();
      ctx.arc(-2 - i * 6, -1, 11 - i, -1.1, 1.1);
      ctx.stroke();
    }

    // Eye.
    ctx.fillStyle = '#fffdf4';
    ctx.beginPath();
    ctx.arc(11, -4, 5.6, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#10222b';
    ctx.beginPath();
    ctx.arc(13, -4, 2.9, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(14, -5.4, 1, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#7b3510';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.arc(14, 5, 5, 0.15, 1.05);
    ctx.stroke();
    ctx.restore();

    // Harpoon gun, aims independently.
    ctx.save();
    ctx.rotate(p.aimAngle);
    const kick = p.recoil * 4;
    ctx.translate(-kick, 0);
    ctx.fillStyle = '#0a222d';
    roundRect(ctx, 0, -7.5, 27, 15, 4.5);
    ctx.fill();
    ctx.fillStyle = '#164457';
    roundRect(ctx, 20, -4.5, 30, 9, 3);
    ctx.fill();
    ctx.fillStyle = '#0a222d';
    roundRect(ctx, 45, -7, 8, 14, 2.5);
    ctx.fill();
    ctx.fillStyle = C.cyan;
    ctx.globalAlpha = 0.8;
    ctx.fillRect(22, -1.5, 25, 3);
    ctx.globalAlpha = 1;
    ctx.fillStyle = C.amber;
    ctx.fillRect(4, -2, 10, 4);
    if (p.triple > 0) {
      ctx.strokeStyle = C.amber;
      ctx.lineWidth = 2;
      for (const off of [-7, 7]) {
        ctx.beginPath();
        ctx.moveTo(40, off * 1.4);
        ctx.lineTo(54, off * 1.4);
        ctx.stroke();
      }
    }
    if (p.muzzle > 0) {
      const s = p.muzzle / 0.075;
      ctx.globalAlpha = s;
      ctx.fillStyle = '#fff6cf';
      ctx.beginPath();
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU;
        const r = i % 2 === 0 ? 12 * s : 4 * s;
        const x = 54 + Math.cos(a) * r;
        const y = Math.sin(a) * r;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = 'rgba(255,194,71,0.5)';
      ctx.beginPath();
      ctx.arc(55, 0, 9 * s, 0, TAU);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.restore();

    ctx.restore();
  }

  drawAimGuide(game) {
    const { ctx, player, aimPoint } = game;
    if (!aimPoint) return;
    const dx = aimPoint.x - player.x;
    const dy = aimPoint.y - player.y;
    const d = Math.hypot(dx, dy);
    if (d < 30) return;
    const ux = dx / d;
    const uy = dy / d;
    ctx.save();
    ctx.strokeStyle = 'rgba(110,243,255,0.22)';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([2, 9]);
    ctx.lineDashOffset = -game.t * 40;
    ctx.beginPath();
    ctx.moveTo(player.x + ux * 58, player.y + uy * 58);
    ctx.lineTo(player.x + ux * Math.min(d, 260), player.y + uy * Math.min(d, 260));
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  }

  /* ================================================================== */
  /*  enemies                                                            */
  /* ================================================================== */

  drawEnemies(game) {
    for (const e of game.enemies) {
      if (e.dead) continue;
      const spawn = clamp(e.spawn, 0, 1);
      const alpha = spawn < 1 ? spawn : 1;
      const scale = 0.65 + 0.35 * (1 - Math.pow(1 - spawn, 3));
      const ctx = game.ctx;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.translate(e.x, e.y);
      ctx.scale(scale, scale);
      if (e.type === 'chomper') this.drawChomper(game, e);
      else if (e.type === 'puffer') this.drawPuffer(game, e);
      else if (e.type === 'jelly') this.drawJelly(game, e);
      else if (e.type === 'shark') this.drawShark(game, e);
      else if (e.type === 'boss') this.drawBoss(game, e);
      if (e.flash > 0) {
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = e.flash * 0.55;
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.ellipse(0, 0, e.radius * 1.05, e.radius * 0.8, 0, 0, TAU);
        ctx.fill();
        ctx.globalCompositeOperation = 'source-over';
      }
      ctx.restore();

      if (e.type !== 'boss' && e.hp < e.maxHp) {
        const w = e.radius * 2.2;
        const x = e.x - w / 2;
        const y = e.y - e.radius - 12;
        const frac = clamp(e.hp / e.maxHp, 0, 1);
        ctx.fillStyle = 'rgba(0,8,12,0.65)';
        roundRect(ctx, x, y, w, 4, 2);
        ctx.fill();
        ctx.fillStyle = frac > 0.55 ? C.green : frac > 0.25 ? C.amber : C.pink;
        roundRect(ctx, x, y, Math.max(2, w * frac), 4, 2);
        ctx.fill();
      }
    }
  }

  drawChomper(game, e) {
    const { ctx, t } = game;
    const s = e.radius / 16;
    ctx.rotate(e.angle);
    const wag = Math.sin(e.t * 11 + e.seed) * 0.5;

    ctx.fillStyle = '#d9422c';
    ctx.beginPath();
    ctx.moveTo(-12 * s, 0);
    ctx.quadraticCurveTo(-25 * s, (-9 - wag * 7) * s, -34 * s, (-4 - wag * 4) * s);
    ctx.quadraticCurveTo(-27 * s, 0, -34 * s, (4 - wag * 4) * s);
    ctx.quadraticCurveTo(-25 * s, (9 - wag * 7) * s, -12 * s, 0);
    ctx.fill();

    ctx.fillStyle = '#b52f24';
    ctx.beginPath();
    ctx.moveTo(-3 * s, -11 * s);
    ctx.lineTo(5 * s, -21 * s);
    ctx.lineTo(11 * s, -9 * s);
    ctx.closePath();
    ctx.fill();

    const g = ctx.createLinearGradient(-16 * s, -10 * s, 16 * s, 10 * s);
    g.addColorStop(0, '#ff9a5b');
    g.addColorStop(0.55, '#f4623c');
    g.addColorStop(1, '#c22f26');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, 0, 17 * s, 11.5 * s, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(90,15,10,0.55)';
    ctx.lineWidth = 1.2;
    ctx.stroke();

    ctx.strokeStyle = 'rgba(120,20,15,0.5)';
    ctx.lineWidth = 2 * s;
    for (let i = 0; i < 2; i++) {
      ctx.beginPath();
      ctx.arc(-2 * s - i * 5 * s, 0, (8 - i * 1.5) * s, -1, 1);
      ctx.stroke();
    }

    // Mouth and teeth.
    ctx.fillStyle = '#3a0c0c';
    ctx.beginPath();
    ctx.ellipse(12 * s, 1.5 * s, 6.5 * s, 5.4 * s, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#fff4e2';
    for (let i = 0; i < 3; i++) {
      const tx = (9 + i * 3.4) * s;
      ctx.beginPath();
      ctx.moveTo(tx - 1.5 * s, -2.8 * s);
      ctx.lineTo(tx + 1.2 * s, -2.8 * s);
      ctx.lineTo(tx - 0.2 * s, 0.4 * s);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(tx - 1.5 * s, 5.2 * s);
      ctx.lineTo(tx + 1.2 * s, 5.2 * s);
      ctx.lineTo(tx - 0.2 * s, 2.4 * s);
      ctx.closePath();
      ctx.fill();
    }

    ctx.fillStyle = '#fffdf4';
    ctx.beginPath();
    ctx.arc(8 * s, -4.5 * s, 4.4 * s, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#171013';
    ctx.beginPath();
    ctx.arc(9.4 * s, -4.5 * s, 2.2 * s, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#5a120c';
    ctx.lineWidth = 2 * s;
    ctx.beginPath();
    ctx.moveTo(4 * s, -9 * s);
    ctx.lineTo(11 * s, -7.4 * s);
    ctx.stroke();
  }

  drawPuffer(game, e) {
    const { ctx, t } = game;
    const s = e.radius / 23;
    const pulse = 1 + Math.sin(t * 3 + e.seed) * 0.035;
    const charging = e.fireT < 0.45;
    ctx.scale(pulse, pulse);

    if (charging) {
      ctx.globalAlpha = 0.25 + 0.2 * Math.sin(t * 20);
      ctx.fillStyle = C.amber;
      ctx.beginPath();
      ctx.arc(0, 0, (30 + Math.sin(t * 12) * 3) * s, 0, TAU);
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    ctx.fillStyle = '#c9861f';
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU + e.t * 0.08;
      const r1 = 21 * s;
      const r2 = 30 * s;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a - 0.13) * r1, Math.sin(a - 0.13) * r1);
      ctx.lineTo(Math.cos(a) * r2, Math.sin(a) * r2);
      ctx.lineTo(Math.cos(a + 0.13) * r1, Math.sin(a + 0.13) * r1);
      ctx.closePath();
      ctx.fill();
    }

    const g = ctx.createRadialGradient(-6 * s, -7 * s, 2, 0, 0, 23 * s);
    g.addColorStop(0, '#ffe58a');
    g.addColorStop(0.6, '#f5c34a');
    g.addColorStop(1, '#c98b1e');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, 0, 21 * s, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(110,70,10,0.4)';
    ctx.lineWidth = 1.4;
    ctx.stroke();

    ctx.fillStyle = 'rgba(140,90,20,0.45)';
    for (const p of [[-7, 4], [6, 8], [9, -7], [-10, -8]]) {
      ctx.beginPath();
      ctx.arc(p[0] * s, p[1] * s, 2.2 * s, 0, TAU);
      ctx.fill();
    }

    ctx.fillStyle = '#fffdf4';
    for (const ex of [-7, 7]) {
      ctx.beginPath();
      ctx.arc(ex * s, -3 * s, 4.4 * s, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = '#1b1710';
    for (const ex of [-7, 7]) {
      ctx.beginPath();
      ctx.arc((ex + 1) * s, -2 * s, 2.2 * s, 0, TAU);
      ctx.fill();
    }
    ctx.strokeStyle = '#7a4c08';
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.arc(0, 10 * s, 4 * s, 0.2, Math.PI - 0.2);
    ctx.stroke();
    ctx.fillStyle = 'rgba(140,90,20,0.5)';
    ctx.beginPath();
    ctx.ellipse(-19 * s, 5 * s, 6 * s, 3 * s, -0.3, 0, TAU);
    ctx.fill();
  }

  drawJelly(game, e) {
    const { ctx, t } = game;
    const s = e.radius / 20;
    const bob = Math.sin(t * 2.4 + e.seed);
    ctx.translate(0, bob * 2);

    ctx.globalAlpha *= 0.92;
    ctx.strokeStyle = 'rgba(220,170,255,0.55)';
    ctx.lineWidth = 1.6;
    ctx.fillStyle = 'rgba(170,90,255,0.12)';
    for (let i = 0; i < 5; i++) {
      const sw = Math.sin(t * 2.2 + i * 1.3 + e.seed) * 6;
      ctx.beginPath();
      ctx.moveTo((-13 + i * 6.5) * s, 10 * s);
      ctx.quadraticCurveTo((-16 + i * 7 + sw) * s, 22 * s, (-12 + i * 6 + sw * 1.4) * s, 34 * s);
      ctx.stroke();
    }

    const g = ctx.createRadialGradient(-4 * s, -8 * s, 2, 0, 0, 22 * s);
    g.addColorStop(0, 'rgba(255,210,255,0.95)');
    g.addColorStop(0.55, 'rgba(190,120,255,0.8)');
    g.addColorStop(1, 'rgba(110,50,190,0.55)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-20 * s, 4 * s);
    ctx.bezierCurveTo(-22 * s, -18 * s, 22 * s, -18 * s, 20 * s, 4 * s);
    ctx.quadraticCurveTo(15 * s, 10 * s, 10 * s, 4 * s);
    ctx.quadraticCurveTo(5 * s, 10 * s, 0, 4 * s);
    ctx.quadraticCurveTo(-5 * s, 10 * s, -10 * s, 4 * s);
    ctx.quadraticCurveTo(-15 * s, 10 * s, -20 * s, 4 * s);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(230,180,255,0.65)';
    ctx.lineWidth = 1.4;
    ctx.stroke();

    ctx.fillStyle = '#2b1236';
    for (const ex of [-6, 6]) {
      ctx.beginPath();
      ctx.arc(ex * s, -4 * s, 2.1 * s, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    for (const ex of [-6, 6]) {
      ctx.beginPath();
      ctx.arc((ex - 0.6) * s, -4.8 * s, 0.7 * s, 0, TAU);
      ctx.fill();
    }
  }

  drawShark(game, e) {
    const { ctx, t } = game;
    const s = e.radius / 33;
    ctx.rotate(e.angle);
    const wind = e.state === 'wind';
    if (wind) {
      ctx.globalAlpha = 0.5 + Math.sin(t * 24) * 0.3;
      ctx.strokeStyle = C.pink;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, 48 * s, 0, TAU);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }
    if (e.state === 'charge') {
      ctx.strokeStyle = 'rgba(160,225,255,0.25)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(-50 * s - i * 12, (-10 + i * 10) * s);
        ctx.lineTo(-20 * s - i * 12, (-10 + i * 10) * s);
        ctx.stroke();
      }
    }

    ctx.fillStyle = '#7e94a6';
    ctx.beginPath();
    ctx.moveTo(-30 * s, 0);
    ctx.quadraticCurveTo(-46 * s, -14 * s, -55 * s, -19 * s);
    ctx.quadraticCurveTo(-45 * s, 0, -55 * s, 19 * s);
    ctx.quadraticCurveTo(-46 * s, 14 * s, -30 * s, 0);
    ctx.fill();

    ctx.fillStyle = '#7a93a6';
    ctx.beginPath();
    ctx.moveTo(-4 * s, -13 * s);
    ctx.lineTo(2 * s, -32 * s);
    ctx.lineTo(14 * s, -12 * s);
    ctx.closePath();
    ctx.fill();

    const g = ctx.createLinearGradient(0, -18 * s, 0, 18 * s);
    g.addColorStop(0, '#b2c5d3');
    g.addColorStop(0.55, '#8ba1b4');
    g.addColorStop(1, '#5e7488');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(2 * s, 0, 42 * s, 16 * s, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#e3edf3';
    ctx.beginPath();
    ctx.ellipse(4 * s, 7 * s, 34 * s, 7.5 * s, 0, 0, TAU);
    ctx.fill();

    ctx.fillStyle = '#6f8496';
    ctx.beginPath();
    ctx.moveTo(-8 * s, 10 * s);
    ctx.lineTo(0, 26 * s);
    ctx.lineTo(10 * s, 10 * s);
    ctx.closePath();
    ctx.fill();

    // Nose, eye, teeth.
    ctx.fillStyle = '#f2f7fa';
    ctx.beginPath();
    ctx.moveTo(43 * s, -4 * s);
    ctx.lineTo(52 * s, 1 * s);
    ctx.lineTo(43 * s, 5 * s);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#11222c';
    ctx.beginPath();
    ctx.arc(24 * s, -4 * s, 2.6 * s, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 4; i++) {
      const tx = (30 + i * 4.2) * s;
      ctx.beginPath();
      ctx.moveTo(tx, 8 * s);
      ctx.lineTo(tx + 2 * s, 8 * s);
      ctx.lineTo(tx + 1 * s, 13 * s);
      ctx.closePath();
      ctx.fill();
    }
    ctx.strokeStyle = 'rgba(40,60,75,0.5)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(24 * s, 8 * s);
    ctx.lineTo(48 * s, 8 * s);
    ctx.stroke();
  }

  drawBoss(game, e) {
    const { ctx, t } = game;
    const s = e.radius / 62;
    const pulse = 1 + Math.sin(t * 2.2) * 0.02;
    const charging = e.mode === 'charge';

    // Aura.
    const aura = ctx.createRadialGradient(0, 0, 20 * s, 0, 0, 100 * s);
    aura.addColorStop(0, charging ? 'rgba(255,80,140,0.18)' : 'rgba(150,90,255,0.15)');
    aura.addColorStop(1, 'rgba(80,20,150,0)');
    ctx.fillStyle = aura;
    ctx.beginPath();
    ctx.arc(0, 0, 100 * s, 0, TAU);
    ctx.fill();

    ctx.save();
    ctx.rotate(e.angle);
    ctx.scale(pulse, pulse);
    const wag = Math.sin(t * 3.4) * 0.5;

    ctx.fillStyle = '#3a1854';
    ctx.beginPath();
    ctx.moveTo(-46 * s, 0);
    ctx.quadraticCurveTo(-72 * s, (-26 - wag * 12) * s, -92 * s, (-30 - wag * 10) * s);
    ctx.quadraticCurveTo(-78 * s, 0, -92 * s, (30 - wag * 10) * s);
    ctx.quadraticCurveTo(-72 * s, (26 - wag * 12) * s, -46 * s, 0);
    ctx.fill();

    ctx.fillStyle = '#4c1f6b';
    ctx.beginPath();
    ctx.moveTo(-24 * s, -34 * s);
    ctx.quadraticCurveTo(-6 * s, -66 * s, 18 * s, -38 * s);
    ctx.closePath();
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-22 * s, 34 * s);
    ctx.quadraticCurveTo(-4 * s, 62 * s, 20 * s, 38 * s);
    ctx.closePath();
    ctx.fill();

    const g = ctx.createRadialGradient(-10 * s, -18 * s, 8 * s, 0, 0, 68 * s);
    g.addColorStop(0, '#8b4fc2');
    g.addColorStop(0.5, '#5b2a83');
    g.addColorStop(1, '#2c123f');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, 0, 58 * s, 42 * s, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(190,120,255,0.25)';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Ridges.
    ctx.strokeStyle = 'rgba(30,10,45,0.7)';
    ctx.lineWidth = 3 * s;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.arc(-8 * s - i * 9 * s, 0, (30 - i * 4) * s, -1.2, 1.2);
      ctx.stroke();
    }

    // Mouth.
    ctx.fillStyle = '#1a061f';
    ctx.beginPath();
    ctx.ellipse(38 * s, 4 * s, 24 * s, 18 * s, 0.05, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#fff6e0';
    for (let i = 0; i < 5; i++) {
      const tx = (23 + i * 6.5) * s;
      ctx.beginPath();
      ctx.moveTo(tx, -9 * s);
      ctx.lineTo(tx + 4.5 * s, -9 * s);
      ctx.lineTo(tx + 2.2 * s, 0);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(tx, 17 * s);
      ctx.lineTo(tx + 4.5 * s, 17 * s);
      ctx.lineTo(tx + 2.2 * s, 7 * s);
      ctx.closePath();
      ctx.fill();
    }

    // Eye.
    ctx.fillStyle = '#ffe0a8';
    ctx.beginPath();
    ctx.arc(18 * s, -16 * s, 8 * s, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#170a1c';
    ctx.beginPath();
    ctx.arc(21 * s, -16 * s, 4 * s, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    ctx.beginPath();
    ctx.arc(22.6 * s, -17.6 * s, 1.4 * s, 0, TAU);
    ctx.fill();

    // Lure.
    ctx.strokeStyle = '#3c1c55';
    ctx.lineWidth = 4 * s;
    ctx.beginPath();
    ctx.moveTo(10 * s, -38 * s);
    ctx.quadraticCurveTo(26 * s, -72 * s, 54 * s, -62 * s);
    ctx.stroke();
    const lure = ctx.createRadialGradient(58 * s, -62 * s, 1, 58 * s, -62 * s, 20 * s);
    lure.addColorStop(0, 'rgba(255,255,220,1)');
    lure.addColorStop(0.35, 'rgba(200,255,120,0.9)');
    lure.addColorStop(1, 'rgba(140,255,80,0)');
    ctx.fillStyle = lure;
    ctx.beginPath();
    ctx.arc(58 * s, -62 * s, 20 * s, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#f4ffd0';
    ctx.beginPath();
    ctx.arc(58 * s, -62 * s, 4 * s, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  /* ================================================================== */
  /*  projectiles / pickups / particles                                  */
  /* ================================================================== */

  drawBullets(game) {
    const { ctx } = game;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const b of game.bullets) {
      const tx = b.x - b.vx * 0.024;
      const ty = b.y - b.vy * 0.024;
      const grad = ctx.createLinearGradient(tx, ty, b.x, b.y);
      grad.addColorStop(0, 'rgba(110,243,255,0)');
      grad.addColorStop(1, 'rgba(190,255,255,0.9)');
      ctx.strokeStyle = grad;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(tx, ty);
      ctx.lineTo(b.x, b.y);
      ctx.stroke();
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(b.x, b.y, 2.4, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  drawEnemyBullets(game) {
    const { ctx } = game;
    for (const b of game.ebullets) {
      ctx.save();
      ctx.translate(b.x, b.y);
      if (b.kind === 'orb') {
        const g = ctx.createRadialGradient(0, 0, 1, 0, 0, 14);
        g.addColorStop(0, 'rgba(255,240,255,0.95)');
        g.addColorStop(0.4, 'rgba(190,110,255,0.8)');
        g.addColorStop(1, 'rgba(120,40,200,0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(0, 0, 14, 0, TAU);
        ctx.fill();
      } else if (b.kind === 'glow') {
        ctx.fillStyle = 'rgba(200,120,255,0.25)';
        ctx.beginPath();
        ctx.arc(0, 0, 13, 0, TAU);
        ctx.fill();
        ctx.fillStyle = '#e0a8ff';
        ctx.beginPath();
        ctx.arc(0, 0, 5, 0, TAU);
        ctx.fill();
      } else {
        ctx.rotate(Math.atan2(b.vy, b.vx));
        ctx.fillStyle = 'rgba(255,194,71,0.25)';
        ctx.beginPath();
        ctx.arc(0, 0, 10, 0, TAU);
        ctx.fill();
        ctx.fillStyle = '#ffd166';
        ctx.beginPath();
        ctx.moveTo(8, 0);
        ctx.lineTo(-4, -4.5);
        ctx.lineTo(-2, 0);
        ctx.lineTo(-4, 4.5);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    }
  }

  drawPickups(game) {
    const { ctx, t } = game;
    for (const it of game.pickups) {
      const def = PICKUP_DEFS[it.type];
      const bob = Math.sin(t * 3 + it.t) * 3;
      const alpha = it.life < 3 ? 0.4 + Math.sin(t * 16) * 0.35 : 1;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.translate(it.x, it.y + bob);
      const g = ctx.createRadialGradient(0, 0, 1, 0, 0, 26);
      g.addColorStop(0, `${def.color}55`);
      g.addColorStop(1, `${def.color}00`);
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(0, 0, 26, 0, TAU);
      ctx.fill();

      ctx.strokeStyle = `${def.color}88`;
      ctx.lineWidth = 1.5;
      ctx.setLineDash([4, 5]);
      ctx.lineDashOffset = -t * 20;
      ctx.beginPath();
      ctx.arc(0, 0, 16 + Math.sin(t * 3 + it.t) * 1.5, 0, TAU);
      ctx.stroke();
      ctx.setLineDash([]);

      if (it.type === 'pearl') {
        ctx.fillStyle = '#f4ffff';
        ctx.beginPath();
        ctx.arc(0, 0, 6.5, 0, TAU);
        ctx.fill();
        ctx.fillStyle = 'rgba(110,243,255,0.7)';
        ctx.beginPath();
        ctx.arc(-2, -2, 2, 0, TAU);
        ctx.fill();
      } else if (it.type === 'heart') {
        ctx.fillStyle = '#ff6b8f';
        ctx.beginPath();
        ctx.moveTo(0, 7);
        ctx.bezierCurveTo(-10, 0, -8, -9, -3.5, -6.5);
        ctx.bezierCurveTo(-1.5, -5.4, 0, -3.2, 0, -3.2);
        ctx.bezierCurveTo(0, -3.2, 1.5, -5.4, 3.5, -6.5);
        ctx.bezierCurveTo(8, -9, 10, 0, 0, 7);
        ctx.fill();
      } else if (it.type === 'triple') {
        ctx.strokeStyle = '#ffc247';
        ctx.lineWidth = 2.2;
        for (const o of [-4, 0, 4]) {
          ctx.beginPath();
          ctx.moveTo(-5 + o, 5);
          ctx.lineTo(3 + o, -6);
          ctx.stroke();
        }
      } else if (it.type === 'rapid') {
        ctx.fillStyle = '#6ef3ff';
        ctx.beginPath();
        ctx.moveTo(1, -7);
        ctx.lineTo(-6, 1);
        ctx.lineTo(-1, 1);
        ctx.lineTo(-2, 8);
        ctx.lineTo(6, -1);
        ctx.lineTo(1, -1);
        ctx.closePath();
        ctx.fill();
      } else if (it.type === 'shield') {
        ctx.fillStyle = 'rgba(143,227,255,0.25)';
        ctx.strokeStyle = '#8fe3ff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, -7);
        ctx.lineTo(6, -4);
        ctx.lineTo(6, 2);
        ctx.quadraticCurveTo(6, 6, 0, 8);
        ctx.quadraticCurveTo(-6, 6, -6, 2);
        ctx.lineTo(-6, -4);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
      }
      ctx.restore();
    }
  }

  drawRings(game) {
    const { ctx } = game;
    for (const r of game.rings) {
      const a = 1 - r.t / r.life;
      ctx.save();
      ctx.globalAlpha = a * 0.8;
      ctx.strokeStyle = r.color;
      ctx.lineWidth = r.width * a;
      ctx.beginPath();
      ctx.arc(r.x, r.y, r.r, 0, TAU);
      ctx.stroke();
      ctx.restore();
    }
  }

  drawParticles(game) {
    const { ctx } = game;
    for (const p of game.particles) {
      const a = clamp(p.life / p.max, 0, 1);
      if (p.type === 'bubble') {
        ctx.globalAlpha = a * 0.5;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, TAU);
        ctx.stroke();
      } else {
        ctx.globalAlpha = a;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * a, 0, TAU);
        ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
  }

  drawTexts(game) {
    const { ctx } = game;
    for (const tx of game.texts) {
      const a = clamp(tx.life / tx.max, 0, 1);
      ctx.save();
      ctx.globalAlpha = a;
      ctx.font = `800 ${tx.size}px ${FONT}`;
      ctx.textAlign = 'center';
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(0,10,16,0.65)';
      ctx.strokeText(tx.text, tx.x, tx.y);
      ctx.fillStyle = tx.color;
      ctx.fillText(tx.text, tx.x, tx.y);
      ctx.restore();
    }
  }

  /* ================================================================== */
  /*  screen-space overlays                                              */
  /* ================================================================== */

  drawScreenFX(game) {
    const { ctx, w, h } = game;
    if (this.vignette) {
      ctx.fillStyle = this.vignette;
      ctx.fillRect(0, 0, w, h);
    }

    if (game.hurtFlash > 0) {
      const g = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.2, w / 2, h / 2, Math.max(w, h) * 0.7);
      g.addColorStop(0, 'rgba(255,30,60,0)');
      g.addColorStop(1, `rgba(255,30,60,${0.42 * game.hurtFlash})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, h);
    }

    if (game.state === 'playing' && game.player.hp / game.player.maxHp < 0.3) {
      const a = 0.08 + Math.sin(game.t * 5) * 0.04;
      const g = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.25, w / 2, h / 2, Math.max(w, h) * 0.7);
      g.addColorStop(0, 'rgba(255,20,50,0)');
      g.addColorStop(1, `rgba(255,20,50,${Math.max(0.03, a)})`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, h);
    }

    // Slow caustic shimmer on top of the scene.
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.035;
    ctx.strokeStyle = '#bffcff';
    ctx.lineWidth = 2;
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      for (let x = 0; x <= w; x += 30) {
        const y = h * 0.15 + i * 48 + Math.sin(x * 0.009 + game.t * 0.5 + i * 1.7) * 12;
        if (x === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    ctx.restore();
  }

  drawReticle(game) {
    const { ctx, input, w, h, t } = game;
    if (input.touchMode) return;
    if (!input.mouse.active) return;
    const mx = input.mouse.x;
    const my = input.mouse.y;
    if (mx < 0 || my < 0 || mx > w || my > h) return;

    let hover = false;
    const viewX = game.camera.x;
    const viewY = game.camera.y;
    for (const e of game.enemies) {
      if (e.dead) continue;
      const ex = e.x - viewX;
      const ey = e.y - viewY;
      if (Math.hypot(ex - mx, ey - my) < e.radius + 14) { hover = true; break; }
    }

    ctx.save();
    ctx.translate(mx, my);
    ctx.rotate(t * 0.7);
    ctx.strokeStyle = hover ? C.pink : 'rgba(190,255,255,0.85)';
    ctx.lineWidth = 1.6;
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.arc(0, 0, 13, i * (TAU / 4) + 0.25, i * (TAU / 4) + 1.05);
      ctx.stroke();
    }
    ctx.rotate(-t * 0.7);
    ctx.fillStyle = hover ? C.pink : C.cyan;
    ctx.beginPath();
    ctx.arc(0, 0, 1.8, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = 0.5;
    for (const [dx, dy] of [[0, -20], [0, 20], [-20, 0], [20, 0]]) {
      ctx.beginPath();
      ctx.moveTo(dx * 0.75, dy * 0.75);
      ctx.lineTo(dx, dy);
      ctx.stroke();
    }
    ctx.restore();
  }
}

import {
  TAU, C, FONT, DISPLAY, clamp, lerp, easeOut, roundRect, formatNumber,
} from './core.js';

function glass(ctx, x, y, w, h, r = 12, tint = 0.52) {
  ctx.save();
  ctx.fillStyle = `rgba(3,17,26,${tint})`;
  roundRect(ctx, x, y, w, h, r);
  ctx.fill();
  ctx.strokeStyle = 'rgba(110,243,255,0.16)';
  ctx.lineWidth = 1;
  roundRect(ctx, x + 0.5, y + 0.5, w - 1, h - 1, r);
  ctx.stroke();
  ctx.restore();
}

function label(ctx, text, x, y, size, color, weight = 700, align = 'left') {
  ctx.font = `${weight} ${size}px ${FONT}`;
  ctx.textAlign = align;
  ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
}

export function drawHUD(game) {
  const { ctx, w, h, safe, player, t } = game;
  if (!player) return;

  const narrow = w < 720;
  const scale = w < 430 ? 0.86 : 1;
  const left = safe.left + 16;
  const top = safe.top + 16;
  const panelW = 188 * scale;
  const panelH = 68 * scale;

  /* ---------------- score / wave ---------------- */
  glass(ctx, left, top, panelW, panelH, 14);
  ctx.save();
  ctx.strokeStyle = 'rgba(255,194,71,0.55)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(left + 12 * scale, top + 12 * scale);
  ctx.lineTo(left + 12 * scale, top + panelH - 12 * scale);
  ctx.stroke();
  ctx.restore();

  label(ctx, `WAVE ${String(Math.max(1, game.wave)).padStart(2, '0')}`, left + 22 * scale, top + 20 * scale, 9.5 * scale, C.cyan, 800);
  const scoreText = formatNumber(game.score);
  ctx.font = `900 ${24 * scale}px ${DISPLAY}`;
  ctx.textAlign = 'left';
  ctx.fillStyle = C.white;
  ctx.shadowColor = 'rgba(110,243,255,0.35)';
  ctx.shadowBlur = 12;
  ctx.fillText(scoreText, left + 20 * scale, top + 50 * scale);
  ctx.shadowBlur = 0;
  label(ctx, 'PTS', left + 22 * scale + ctx.measureText(scoreText).width + 5 * scale, top + 50 * scale, 8.5 * scale, 'rgba(143,185,196,0.75)', 700);

  /* ---------------- combo ---------------- */
  let stackY = top + panelH + 9;
  const hasBoss = !!game.boss;
  let bossH = 0;

  if (game.combo > 1) {
    const mult = game.comboMult();
    const cw = 150 * scale;
    const ch = 30 * scale;
    glass(ctx, left, stackY, cw, ch, 9, 0.42);
    ctx.font = `900 ${17 * scale}px ${DISPLAY}`;
    ctx.textAlign = 'left';
    ctx.fillStyle = C.amber;
    ctx.fillText(`${mult.toFixed(1)}×`, left + 10 * scale, stackY + 21 * scale);
    label(ctx, `${game.combo} COMBO`, left + 52 * scale, stackY + 19 * scale, 9 * scale, '#d9fbff', 800);
    const frac = clamp(game.comboTimer / 3.4, 0, 1);
    ctx.fillStyle = 'rgba(255,194,71,0.18)';
    roundRect(ctx, left + 8 * scale, stackY + ch - 5 * scale, cw - 16 * scale, 2.5 * scale, 2);
    ctx.fill();
    ctx.fillStyle = C.amber;
    roundRect(ctx, left + 8 * scale, stackY + ch - 5 * scale, (cw - 16 * scale) * frac, 2.5 * scale, 2);
    ctx.fill();
    stackY += ch + 7;
  }

  /* ---------------- boss bar ---------------- */
  if (hasBoss) {
    const bw = narrow ? w - left - safe.right - 16 : Math.min(440, w * 0.42);
    const bx = narrow ? left : (w - bw) / 2;
    const by = narrow ? top + panelH + 10 : safe.top + 16;
    bossH = 34 * scale;
    const frac = clamp(game.boss.hp / game.boss.maxHp, 0, 1);
    ctx.font = `900 ${11 * scale}px ${DISPLAY}`;
    ctx.textAlign = narrow ? 'left' : 'center';
    ctx.fillStyle = '#e3c9ff';
    ctx.shadowColor = 'rgba(177,110,255,0.6)';
    ctx.shadowBlur = 10;
    ctx.fillText('ANGLERFISH', narrow ? bx + 2 : w / 2, by + 10 * scale);
    ctx.shadowBlur = 0;
    if (narrow) {
      ctx.textAlign = 'right';
      label(ctx, `${Math.ceil(frac * 100)}%`, bx + bw, by + 10 * scale, 9 * scale, 'rgba(227,201,255,0.75)', 700);
    }
    const barY = by + 16 * scale;
    const barH = 10 * scale;
    ctx.fillStyle = 'rgba(5,10,20,0.72)';
    roundRect(ctx, bx, barY, bw, barH, barH / 2);
    ctx.fill();
    const g = ctx.createLinearGradient(bx, 0, bx + bw, 0);
    g.addColorStop(0, '#7b3fff');
    g.addColorStop(0.55, '#c06bff');
    g.addColorStop(1, '#ff5d8f');
    ctx.fillStyle = g;
    if (frac > 0) {
      roundRect(ctx, bx + 1, barY + 1, Math.max(3, (bw - 2) * frac), barH - 2, (barH - 2) / 2);
      ctx.fill();
    }
    ctx.strokeStyle = 'rgba(200,150,255,0.4)';
    ctx.lineWidth = 1;
    roundRect(ctx, bx, barY, bw, barH, barH / 2);
    ctx.stroke();
    if (narrow) stackY = Math.max(stackY, by + bossH + 6);
  }

  /* ---------------- power-ups ---------------- */
  const power = [
    ['3×', player.triple, C.amber, 10],
    ['RPD', player.rapid, C.cyan, 10],
    ['SHD', player.shield, C.cyanSoft, 12],
  ].filter((p) => p[1] > 0);
  if (power.length) {
    let px = left;
    const py = stackY;
    for (const [name, timer, color, max] of power) {
      const pw = 58 * scale;
      const ph = 23 * scale;
      glass(ctx, px, py, pw, ph, 7, 0.48);
      label(ctx, name, px + 7 * scale, py + 15 * scale, 8 * scale, color, 900);
      label(ctx, `${timer.toFixed(1)}s`, px + pw - 6 * scale, py + 15 * scale, 7.5 * scale, 'rgba(230,255,255,0.8)', 700, 'right');
      ctx.fillStyle = `${color}44`;
      ctx.fillRect(px + 6 * scale, py + ph - 4 * scale, pw - 12 * scale, 2);
      ctx.fillStyle = color;
      ctx.fillRect(px + 6 * scale, py + ph - 4 * scale, (pw - 12 * scale) * clamp(timer / max, 0, 1), 2);
      px += pw + 6 * scale;
    }
  }

  /* ---------------- health / ammo ---------------- */
  const hpW = Math.min(250 * scale, w - safe.left - safe.right - 32);
  const hpH = 68 * scale;
  const hpX = left;
  const hpY = h - safe.bottom - 16 - hpH;
  glass(ctx, hpX, hpY, hpW, hpH, 14);

  const hpFrac = clamp(player.hp / player.maxHp, 0, 1);
  label(ctx, 'HEALTH', hpX + 12 * scale, hpY + 16 * scale, 8.5 * scale, 'rgba(180,225,232,0.8)', 800);
  label(ctx, `${Math.ceil(player.hp)}`, hpX + hpW - 12 * scale, hpY + 17 * scale, 10 * scale, hpFrac < 0.3 ? C.pink : '#dffeff', 800, 'right');

  const barX = hpX + 12 * scale;
  const barY = hpY + 23 * scale;
  const barW = hpW - 24 * scale;
  const barH = 9 * scale;
  ctx.fillStyle = 'rgba(0,8,12,0.7)';
  roundRect(ctx, barX, barY, barW, barH, barH / 2);
  ctx.fill();
  const hpColor = hpFrac > 0.55 ? C.green : hpFrac > 0.28 ? C.amber : C.pink;
  const hg = ctx.createLinearGradient(barX, 0, barX + barW, 0);
  hg.addColorStop(0, hpFrac > 0.55 ? '#37d9a0' : hpFrac > 0.28 ? '#ffb340' : '#ff4d72');
  hg.addColorStop(1, hpColor);
  ctx.fillStyle = hg;
  if (hpFrac > 0) {
    roundRect(ctx, barX + 1, barY + 1, Math.max(2, (barW - 2) * hpFrac), barH - 2, (barH - 2) / 2);
    ctx.fill();
  }
  ctx.strokeStyle = 'rgba(200,255,255,0.13)';
  ctx.lineWidth = 1;
  roundRect(ctx, barX, barY, barW, barH, barH / 2);
  ctx.stroke();

  // Ammo pips / reload.
  const ammoY = hpY + 48 * scale;
  const pipW = Math.min(8 * scale, (barW - 11 * 3) / 12);
  const gap = 3 * scale;
  label(ctx, 'HARPOON', barX, ammoY + 7 * scale, 7 * scale, 'rgba(180,225,232,0.6)', 800);
  const pipsX = barX + 47 * scale;
  if (player.reloading > 0) {
    ctx.fillStyle = 'rgba(255,255,255,0.12)';
    roundRect(ctx, pipsX, ammoY, barW - 47 * scale, 7 * scale, 3.5);
    ctx.fill();
    ctx.fillStyle = C.amber;
    const frac = 1 - player.reloading / 1.05;
    roundRect(ctx, pipsX, ammoY, Math.max(2, (barW - 47 * scale) * frac), 7 * scale, 3.5);
    ctx.fill();
    label(ctx, 'RELOAD', barX + barW, ammoY + 7 * scale, 7 * scale, C.amber, 800, 'right');
  } else {
    for (let i = 0; i < player.mag; i++) {
      const on = i < player.ammo;
      ctx.fillStyle = on ? C.amber : 'rgba(255,255,255,0.13)';
      roundRect(ctx, pipsX + i * (pipW + gap), ammoY, pipW, 7 * scale, 2);
      ctx.fill();
    }
  }

  /* ---------------- dash cooldown ring (desktop) ---------------- */
  if (!game.input.touchMode) {
    const cx = w - safe.right - 66;
    const cy = h - safe.bottom - 76;
    const ready = player.dashCd <= 0;
    ctx.save();
    ctx.globalAlpha = ready ? 0.85 : 0.45;
    ctx.strokeStyle = ready ? C.cyan : 'rgba(143,185,196,0.5)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(cx, cy, 22, 0, TAU);
    ctx.stroke();
    if (!ready) {
      ctx.strokeStyle = C.amber;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(cx, cy, 22, -Math.PI / 2, -Math.PI / 2 + TAU * (1 - player.dashCd / player.dashMax));
      ctx.stroke();
    }
    ctx.fillStyle = ready ? C.cyan : 'rgba(143,185,196,0.7)';
    ctx.font = `900 16px ${FONT}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('»', cx, cy - 1);
    ctx.font = `800 7px ${FONT}`;
    ctx.fillStyle = 'rgba(180,225,232,0.7)';
    ctx.fillText('SHIFT', cx, cy + 34);
    ctx.restore();
  }

  /* ---------------- off-screen danger markers ---------------- */
  if (game.state === 'playing') {
    for (const e of game.enemies) {
      if (e.dead || e.type === 'chomper' || e.type === 'jelly') continue;
      const sx = e.x - game.camera.x;
      const sy = e.y - game.camera.y;
      if (sx > -30 && sx < w + 30 && sy > -30 && sy < h + 30) continue;
      const dx = sx - w / 2;
      const dy = sy - h / 2;
      const pad = 34;
      let tt = Infinity;
      if (dx > 0) tt = Math.min(tt, (w - pad - w / 2) / dx);
      if (dx < 0) tt = Math.min(tt, (pad - w / 2) / dx);
      if (dy > 0) tt = Math.min(tt, (h - pad - h / 2) / dy);
      if (dy < 0) tt = Math.min(tt, (pad - h / 2) / dy);
      if (!isFinite(tt)) continue;
      const ex = w / 2 + dx * tt;
      const ey = h / 2 + dy * tt;
      const ang = Math.atan2(dy, dx);
      const boss = e.type === 'boss';
      ctx.save();
      ctx.translate(ex, ey);
      ctx.rotate(ang);
      ctx.globalAlpha = 0.75;
      ctx.fillStyle = boss ? C.violet : C.pink;
      ctx.beginPath();
      ctx.moveTo(boss ? 14 : 9, 0);
      ctx.lineTo(boss ? -5 : -4, boss ? -8 : -5);
      ctx.lineTo(boss ? -5 : -4, boss ? 8 : 5);
      ctx.closePath();
      ctx.fill();
      if (boss) {
        ctx.rotate(-ang);
        ctx.font = `900 9px ${FONT}`;
        ctx.textAlign = 'center';
        ctx.fillStyle = '#e3c9ff';
        ctx.fillText('BOSS', 0, -14);
      }
      ctx.restore();
    }
  }

  /* ---------------- wave banner ---------------- */
  const b = game.banner;
  if (b) {
    const inA = clamp(b.t / 0.22, 0, 1);
    const outA = clamp((b.dur - b.t) / 0.4, 0, 1);
    const a = Math.min(inA, outA);
    const pop = 1 + (1 - easeOut(inA)) * 0.12;
    const cy = h * 0.28;
    ctx.save();
    ctx.globalAlpha = a;
    ctx.translate(w / 2, cy);
    ctx.scale(pop, pop);
    const lineW = Math.min(w * 0.42, 210);
    ctx.strokeStyle = `${b.color}88`;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(-lineW - 20, 0);
    ctx.lineTo(-24, 0);
    ctx.moveTo(24, 0);
    ctx.lineTo(lineW + 20, 0);
    ctx.stroke();
    ctx.fillStyle = b.color;
    ctx.save();
    ctx.rotate(Math.PI / 4);
    ctx.fillRect(-3, -3, 6, 6);
    ctx.restore();

    const size = Math.min(54, w * 0.1);
    ctx.font = `900 ${size}px ${DISPLAY}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.lineWidth = Math.max(2, size * 0.06);
    ctx.strokeStyle = 'rgba(0,8,14,0.7)';
    ctx.strokeText(b.title, 0, 0);
    ctx.fillStyle = b.color;
    ctx.shadowColor = b.color;
    ctx.shadowBlur = 22;
    ctx.fillText(b.title, 0, 0);
    ctx.shadowBlur = 0;
    ctx.font = `800 ${Math.max(9, 10.5)}px ${FONT}`;
    ctx.fillStyle = 'rgba(226,252,255,0.8)';
    ctx.fillText(b.sub, 0, size * 0.62 + 8);
    ctx.restore();
  }
}

export function drawTouchControls(game) {
  const { ctx, input, w, h, safe, player } = game;
  if (!input.touchMode) return;

  // Aim guide for the right thumb.
  if (input.aim.active && input.aim.mag > 0.16) {
    const len = Math.hypot(input.aim.dx, input.aim.dy) || 1;
    const dx = input.aim.dx / len;
    const dy = input.aim.dy / len;
    const px = player.x - game.camera.x;
    const py = player.y - game.camera.y;
    ctx.save();
    ctx.strokeStyle = 'rgba(110,243,255,0.22)';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([3, 8]);
    ctx.beginPath();
    ctx.moveTo(px + dx * 40, py + dy * 40);
    ctx.lineTo(px + dx * 150, py + dy * 150);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.strokeStyle = 'rgba(190,255,255,0.55)';
    ctx.beginPath();
    ctx.arc(px + dx * 155, py + dy * 155, 7, 0, TAU);
    ctx.stroke();
    ctx.restore();
  }

  for (const stick of [input.move, input.aim]) {
    if (!stick.active) continue;
    const isAim = stick === input.aim;
    const color = isAim ? C.amber : C.cyan;
    ctx.save();
    ctx.globalAlpha = 0.55;
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(stick.ox, stick.oy, isAim ? 56 : 62, 0, TAU);
    ctx.stroke();
    ctx.globalAlpha = 0.12;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(stick.ox, stick.oy, isAim ? 56 : 62, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = 0.85;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(stick.ox + stick.dx, stick.oy + stick.dy, isAim ? 20 : 23, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = 0.4;
    ctx.fillStyle = '#02131c';
    ctx.beginPath();
    ctx.arc(stick.ox + stick.dx, stick.oy + stick.dy, isAim ? 14 : 16, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  // Dash button.
  const b = input.dashButton;
  const ready = player.dashCd <= 0;
  ctx.save();
  ctx.translate(b.x, b.y);
  ctx.globalAlpha = ready ? 0.9 : 0.5;
  ctx.fillStyle = 'rgba(4,20,30,0.58)';
  ctx.beginPath();
  ctx.arc(0, 0, b.r, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = ready ? C.cyan : 'rgba(143,185,196,0.45)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(0, 0, b.r, 0, TAU);
  ctx.stroke();
  if (!ready) {
    ctx.strokeStyle = C.amber;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(0, 0, b.r + 2, -Math.PI / 2, -Math.PI / 2 + TAU * (1 - player.dashCd / player.dashMax));
    ctx.stroke();
  }
  ctx.fillStyle = ready ? C.cyan : 'rgba(180,225,232,0.6)';
  ctx.font = `900 ${b.r * 0.62}px ${FONT}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('»', 0, -b.r * 0.08);
  ctx.font = `800 ${b.r * 0.23}px ${FONT}`;
  ctx.fillStyle = ready ? 'rgba(220,255,255,0.8)' : 'rgba(180,225,232,0.5)';
  ctx.fillText('DASH', 0, b.r * 0.44);
  ctx.restore();

  // A quiet hint for the first few seconds of a run.
  if (game.state === 'playing' && game.wave === 1 && game.t < 9) {
    ctx.save();
    ctx.globalAlpha = clamp(9 - game.t, 0, 1) * 0.7;
    const y = h - safe.bottom - 16;
    ctx.font = `800 8.5px ${FONT}`;
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(226,252,255,0.85)';
    ctx.fillText('LEFT THUMB SWIM', w * 0.25, y - 2);
    ctx.fillText('RIGHT THUMB AIM + FIRE', w * 0.72, y - 2);
    ctx.restore();
  }
}

import { AudioEngine } from './audio.js';
import { Input } from './input.js';
import { Game } from './game.js';
import { formatNumber } from './core.js';

const canvas = document.getElementById('game');
const menuScreen = document.getElementById('menuScreen');
const pauseScreen = document.getElementById('pauseScreen');
const overScreen = document.getElementById('overScreen');
const pauseBtn = document.getElementById('pauseBtn');
const muteBtn = document.getElementById('muteBtn');
const playBtn = document.getElementById('playBtn');
const resumeBtn = document.getElementById('resumeBtn');
const restartBtn = document.getElementById('restartBtn');
const quitBtn = document.getElementById('quitBtn');
const retryBtn = document.getElementById('retryBtn');
const menuBtn = document.getElementById('menuBtn');
const bestMenu = document.getElementById('bestMenu');
const finalScore = document.getElementById('finalScore');
const statWave = document.getElementById('statWave');
const statKills = document.getElementById('statKills');
const statBest = document.getElementById('statBest');
const newBest = document.getElementById('newBest');

const audio = new AudioEngine();
const input = new Input(canvas);

function setVisible(el, visible) {
  el.classList.toggle('hidden', !visible);
  el.setAttribute('aria-hidden', visible ? 'false' : 'true');
}

function syncMute() {
  muteBtn.classList.toggle('muted', audio.muted);
  muteBtn.setAttribute('aria-label', audio.muted ? 'Unmute sound' : 'Mute sound');
  muteBtn.title = audio.muted ? 'Unmute sound (M)' : 'Mute sound (M)';
}

const game = new Game(canvas, input, audio, {
  onState(state, stats) {
    const playing = state === 'playing' || state === 'dying';
    document.body.classList.toggle('playing', playing);

    if (state === 'menu') {
      setVisible(menuScreen, true);
      setVisible(pauseScreen, false);
      setVisible(overScreen, false);
      pauseBtn.classList.add('hidden');
      bestMenu.textContent = formatNumber(game.best);
      syncMute();
    } else if (state === 'playing') {
      setVisible(menuScreen, false);
      setVisible(pauseScreen, false);
      setVisible(overScreen, false);
      pauseBtn.classList.remove('hidden');
    } else if (state === 'paused') {
      setVisible(pauseScreen, true);
      pauseBtn.classList.add('hidden');
    } else if (state === 'dying') {
      setVisible(pauseScreen, false);
      setVisible(overScreen, false);
      pauseBtn.classList.add('hidden');
    } else if (state === 'gameover') {
      setVisible(overScreen, true);
      pauseBtn.classList.add('hidden');
      finalScore.textContent = formatNumber(stats.score);
      statWave.textContent = String(stats.wave);
      statKills.textContent = formatNumber(stats.kills);
      statBest.textContent = formatNumber(stats.best);
      newBest.classList.toggle('hidden', !stats.isBest);
      bestMenu.textContent = formatNumber(stats.best);
      retryBtn.focus({ preventScroll: true });
    }
  },
});

function startRun() {
  audio.init();
  game.start();
}

playBtn.addEventListener('click', startRun);
retryBtn.addEventListener('click', startRun);
resumeBtn.addEventListener('click', () => game.resume());

restartBtn.addEventListener('click', () => {
  audio.init();
  game.start();
});
quitBtn.addEventListener('click', () => game.quitToMenu());
menuBtn.addEventListener('click', () => game.quitToMenu());

pauseBtn.addEventListener('click', () => {
  if (game.state === 'playing') game.pause();
  else if (game.state === 'paused') game.resume();
});

muteBtn.addEventListener('click', () => {
  audio.init();
  audio.toggleMuted();
  syncMute();
});

window.addEventListener('keydown', (e) => {
  if (e.repeat) return;

  if (e.code === 'KeyM') {
    audio.init();
    audio.toggleMuted();
    syncMute();
    return;
  }

  if (e.code === 'Escape' || e.code === 'KeyP') {
    if (game.state === 'playing') game.pause();
    else if (game.state === 'paused') game.resume();
    return;
  }

  if (e.code === 'Enter') {
    if (game.state === 'menu') startRun();
    else if (game.state === 'gameover') startRun();
    else if (game.state === 'paused') game.resume();
    else if (game.state === 'dying') e.preventDefault();
  }
});

syncMute();

// Friendly console note for anyone poking around.
console.log('%cREEF RAMPAGE', 'font:900 20px Arial Black;color:#ffc247;text-shadow:0 0 8px #ff7a3d', '— one fish, one harpoon, zero chill.');

