import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.locator('#playBtn').click();
await page.waitForFunction(() => window.__reef?.state === 'playing', null, { timeout: 15000 });

// pause / resume through the real controls
await page.keyboard.press('Escape');
const paused = await page.evaluate(() => ({ state: window.__reef.state, visible: !document.getElementById('pauseScreen').classList.contains('hidden') }));
await page.locator('#resumeBtn').click();
await page.waitForFunction(() => window.__reef.state === 'playing');
const resumed = await page.evaluate(() => window.__reef.state);

// triple shot + rapid cadence
const shots = await page.evaluate(() => {
  const g = window.__reef;
  g.bullets = [];
  g.player.triple = 6; g.player.rapid = 6; g.player.ammo = 12; g.player.reloading = 0; g.player.fireCd = 0;
  g.player.aimAngle = 0;
  g.fire();
  const n = g.bullets.length;
  const angles = g.bullets.map((b) => Math.atan2(b.vy, b.vx).toFixed(2));
  const cd = +g.player.fireCd.toFixed(3);
  return { bullets: n, angles, cd };
});

// dash
const dash = await page.evaluate(() => {
  const g = window.__reef;
  g.player.dashCd = 0; g.player.dashTime = 0; g.player.vx = 0; g.player.vy = 0;
  g.player.x = 1400; g.player.y = 1400;
  const before = { x: g.player.x, y: g.player.y };
  g.tryDash({ x: 0, y: 0 });
  const started = { dashTime: +g.player.dashTime.toFixed(2), cd: +g.player.dashCd.toFixed(2), vx: Math.round(g.player.vx), vy: Math.round(g.player.vy), invuln: +g.player.invuln.toFixed(2) };
  return { before, started };
});
await page.waitForTimeout(1200);
const afterDash = await page.evaluate(() => ({ x: Math.round(window.__reef.player.x), y: Math.round(window.__reef.player.y), dashTime: window.__reef.player.dashTime, cd: +window.__reef.player.dashCd.toFixed(1) }));

// combo multiplier
const combo = await page.evaluate(() => {
  const g = window.__reef;
  g.enemies = []; g.spawnQueue = []; g.combo = 0; g.comboTimer = 0; g.score = 0;
  for (let i = 0; i < 3; i++) {
    const e = g.spawnEnemy('chomper', g.player.x + 80 + i * 4, g.player.y + 10);
    e.spawn = 1; e.hp = 1;
    g.killEnemy(e);
  }
  return { combo: g.combo, mult: g.comboMult(), score: g.score, timer: +g.comboTimer.toFixed(2), best: g.bestCombo };
});

// combo decay
await page.waitForFunction(() => window.__reef.combo === 0, null, { timeout: 15000 });
const decayed = await page.evaluate(() => ({ combo: window.__reef.combo, timer: window.__reef.comboTimer }));

console.log(JSON.stringify({ paused, resumed, shots, dash, afterDash, combo, decayed, errors }));
await browser.close();

